// GENERATED by scripts/crawler-content.mjs from src/world/tickets + src/world/kb.
// Do not edit by hand; re-run the script after changing ticket content.
import type { CrawlerTicket } from './ticket-type';

export const TICKETS: readonly CrawlerTicket[] = [
  {"id":"ticket:fan-noise","title":"PC sounds like a hornet in a biscuit tin","body":"Filed by you, about your own desk, because the process insists that work without a ticket did not happen. The noise started \"around the time the cleaner came through\", which is correct about the timing and wrong about the cause.","reporter":"Pat Pending","reporterTitle":"IT Support Analyst","archetype":"hidden_cause","cause":"The chassis fan is fouled and has wedged itself against the case.","fixes":["One firm tap, via About This Workstation","Escalate it: this one wants a screwdriver and a spare part"],"urgency":1,"claimed":2,"kb":{"title":"A fan that sounds like a hornet in a biscuit tin","resolution":["Listen to it, and get the reporter to say when it started. A noise that arrived with a house move is a cable in the blade.","Free the blade: reseat the fan, or shift whatever it is rubbing against. About This Workstation has the one honest button for it.","If the noise survives that, the bearing is going. Escalate it with a symptom and what you tried, because that is a part, a screwdriver and somebody on site.","Do not leave it running hot and quiet. A machine that overheats silently is a worse ticket than one that buzzes loudly."]}},
  {"id":"ticket:rotated-screen","title":"I have been hacked and I want it logged","body":"Ada reports that her screen \"went sideways on its own\" over the weekend and would like to know whether the police need to be involved. She mentions, as an unrelated aside, that a colleague was messing about at her desk on Friday afternoon.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"hidden_cause","cause":"Somebody pressed the screen-rotation shortcut on SALES-02 and left for the weekend.","fixes":["Turn the display back with rotate SALES-02 0","Fix it on her screen through Remote Assist","Talk her through the shortcut herself, over chat"],"urgency":2,"claimed":3,"kb":{"title":"The screen that went sideways on its own","resolution":["Confirm what the reporter is seeing: the picture is turned, the mouse still moves the way it always did, and nothing else is wrong.","Set the rotation back to 0 - \"rotate <host> 0\" in the terminal, or the control on the remote screen in Remote Assist. Both do the same thing to the same machine.","Tell the reporter, out loud, that nothing was accessed and their password is fine. They have spent the morning assuming otherwise.","Mention the shortcut - Control, Alt and an arrow key - so the next person who leans on their keyboard knows what they have done."]}},
  {"id":"ticket:locked-account","title":"Computer says the password is wrong (it is not wrong)","body":"Gary is back from two weeks away and cannot get in. He has read the message on his screen out to you twice - \"This account has been locked out, please contact support\" - without noticing that it is also the answer. He is typing the password correctly. That was never the problem.","reporter":"Gary Poole","reporterTitle":"Payroll Clerk","archetype":"read_the_screen","cause":"The lockout tripped this morning after five failed attempts and nothing has cleared it since. Gary has been away a fortnight and has not signed in once in that time, which is the other half of the story the directory tells.","fixes":["Unlock the account in Active Dictionary","Unlock it with unlock gpoole"],"urgency":3,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:wedged-spooler","title":"The printer is haunted","body":"Nina reports that the Hercules 400 hums, flashes and prints nothing. There are 47 jobs queued behind whatever it is brooding about, four of which are the same delivery note re-sent by increasingly short-tempered people.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"hidden_cause","cause":"The spooler on PRINT-01 wedged on a malformed job and everything sent since has piled up behind it.","fixes":["clearqueue on the Hercules - which stops the spooler and drops the files it had open - then restart spooler","Stop the spooler and empty the queue from the hardware panel on PRINT-01, then start the spooler again from its taskbar"],"urgency":3,"claimed":3,"kb":{"title":"The print spooler, and why the queue goes first","resolution":["Look at the queue: \"queue <printer>\" says how many jobs are stacked up behind whatever jammed, and what the spooler reports.","Those jobs are files, and files are in a directory. \"dir \\\\PRINT-01\\C$\\WINDOWS\\SYSTEM32\\SPOOL\\PRINTERS\" is the same backlog with a date and a size on every line of it - and four files of exactly the same size are four copies of the same delivery note, which is the thing the reporter has not told you.","STOP THE SPOOLER, then empty the queue. The queued jobs are files on disk and the running service has them open, which is exactly when deleting them fails. On this estate those are one control - \"clearqueue <printer>\", or the hardware panel in Remote Assist - and it stops the service before it drops anything.","Start the spooler again: \"restart spooler\", or its taskbar entry on the print server. It is deliberately left stopped until you do, because that is the third step and it is yours."]}},
  {"id":"ticket:tidied-list","title":"The printer works for everyone except me","body":"Bev on reception reports that her print jobs go nowhere. She has watched Nina print the same document from the next desk, on the same printer, while hers did not arrive. She has already been told twice this morning that the printer is fixed, and would like it noted that she is not making it up.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"hidden_cause","cause":"Bev's account was taken out of Print Users during a tidy-up in March, and the print server has been obeying that ever since.","fixes":["Put the account back into Print Users in Active Dictionary"],"urgency":2,"claimed":3,"kb":{"title":"When the printer works for everybody except one person","resolution":["Ask who else is affected. One desk means permissions; the whole floor means the spooler.","Check the group in Active Dictionary against somebody who CAN print, rather than against what you expect to see.","Add the account back to Print Users.","Record it as what happened - \"re-added to Print Users\" - because the next person to read this ticket is three weeks away and it is you."]}},
  {"id":"ticket:boss-phone","title":"My phone has stopped getting email (top priority)","body":"Desmond reports, in chat, that his phone has not had a mail since yesterday and that he has the eleven o'clock. He would like it treated as the most important thing on the desk. He has not mentioned it to anybody else, on the grounds that telling you is faster than writing it down, and telling you twice is faster still.","reporter":"Desmond Frisk","reporterTitle":"Service Delivery Lead","archetype":"deadline_absurdity","cause":"Desmond's account came out of VPN Users in a group tidy-up, and the phone has had nothing to sync against since.","fixes":["Put the account back in VPN Users in Active Dictionary"],"urgency":1,"claimed":3,"kb":{"title":"A phone that has stopped getting mail","resolution":["Check whether mail is arriving anywhere else. Desktop fine, phone not, means the mailbox is fine and the path to it is not.","Check group membership in Active Dictionary before touching the handset. Remote mail here needs VPN Users.","Put the account back in the group and say so on the ticket in the words of what happened.","Only then look at the phone - and remember that re-adding an account destroys the evidence along with the twenty minutes."]}},
  {"id":"ticket:mfa-reregister","title":"The code app on my new phone has no codes in it","body":"Priya has a new phone. The authenticator moved across with everything else and is sitting there, installed, empty and cheerful. She has read the sentence about restoring from a backup four times and is now describing it to you in a tone of voice.","reporter":"Priya Raval","reporterTitle":"Accounts Payable","archetype":"hidden_cause","cause":"The second factor was bound to a phone that has been traded in. Nothing is broken; the binding simply is not there any more, and only a new enrolment puts one back.","fixes":["Prove who she is through a channel her account already has - \"verify callback praval\" or \"verify code praval\" - then enrol the new phone with \"mfa praval\"","Do it now, while she is on the line, and get on with the queue"],"urgency":3,"claimed":3,"kb":{"title":"A new phone, and an authenticator with nothing in it","resolution":["Read the account first. If the second factor is still enrolled, the problem is the app or the clock on the phone, not the account.","PROVE WHO YOU ARE TALKING TO before you enrol anything, and prove it with something the ACCOUNT has rather than something the caller can tell you. Four channels count on this estate: a callback to the number the directory already holds, the recovery code issued in the June envelope, an in-person check, or a recovery contact nominated in advance.","A payroll number, a hiring manager and a desk are NOT any of those. They are on a payslip, on the company website and on a seating plan. Somebody ringing to take an account off you will have all three, and will be apologetic about only having three.","Record which channel you used - \"verify callback <account>\", or the option in the conversation. \"Verified\" is not an answer to how, and how is what the incident report asks."]}},
  {"id":"ticket:must-change-password","title":"This keeps happening and I do not know what to do","body":"Terry reports a box that appears every morning. He has helpfully typed out what it says: \"Your password has expired. Click Continue to change it.\" He has not clicked Continue. He would like somebody to come and look at the box.","reporter":"Terry Blunt","reporterTitle":"Estimating","archetype":"read_the_screen","cause":"The password policy expired his credential overnight, and the box on his screen is the fix, phrased as an instruction, with a button on it.","fixes":["Reset it in Active Dictionary and tell him what the box wanted","reset tblunt, then read him his own screenshot back"],"urgency":2,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:stale-device-relock","title":"You unlocked it yesterday and it locked itself again","body":"Hilda has been locked out three times since Tuesday. Each time somebody has unlocked it, each time she has got about ten minutes of work done, and each time it has shut again. She has changed her password twice and would like to know what she is doing wrong. She is not doing anything wrong.","reporter":"Hilda Marsh","reporterTitle":"Warehouse Supervisor","archetype":"hidden_cause","cause":"The scanning tablet in the warehouse cupboard still holds the password she had before the spring, and offers it to the directory every few minutes until the count reaches five.","fixes":["forget the tablet's stored password, then unlock hmarsh","Unlock her in Active Dictionary, watch it go again, then find the tablet"],"urgency":3,"claimed":3,"kb":{"title":"The account that locks itself again ten minutes later","resolution":["Unlock it, then look at the bad password count over the next few minutes. A count that climbs while the user is not typing is the whole diagnosis.","Open Event Viewer on the machines around them and read the 4625s. The interval between them is the giveaway: people are irregular, and a device is not.","Find what holds the old credential - the tablet in the cupboard, the scanner, the account on the shared machine - and clear it.","THEN unlock the account. Doing it the other way round works too, and you will do it the other way round once, and then never again."]}},
  {"id":"ticket:mailbox-access","title":"Please add me to the Sales mailbox","body":"Kwame is on the Sales mailbox rota from tomorrow and cannot see it. Ada has forwarded the request with the words \"as discussed\", which refers to a discussion nobody has minuted and which Kwame was not in. He is being extremely polite about all of it.","reporter":"Kwame Boateng","reporterTitle":"Sales Executive","archetype":"hidden_cause","cause":"Nobody has ever granted him access. The mailbox is fine and the request is the whole of the fault.","fixes":["Grant Full Access on the Sales mailbox to kboateng"],"urgency":2,"claimed":2,"kb":{"title":"Full Access and Send As are two permissions","resolution":["Grant Full Access on the mailbox. That is what lets somebody open it, read it and file things in it.","Then ask the question the request did not: will they be REPLYING from it? If anybody answers yes, they need Send As as well.","Add the account to the Send As group for that mailbox. On this estate that is where the permission lives.","Say both out loud on the ticket. The next person to read the request will read it exactly as literally as you did."]}},
  {"id":"ticket:sendas-missing","title":"I can see the Sales mailbox now but it will not let me send","body":"Kwame can read everything, file everything and reply to nothing. The error is one line long and mentions neither permissions nor the mailbox. He has apologised twice for coming back, which is two more apologies than this deserves from him.","reporter":"Kwame Boateng","reporterTitle":"Sales Executive","archetype":"hidden_cause","cause":"Full Access lets somebody open a mailbox. Sending as it is a second permission, granted somewhere else - on this estate, by a group - and the first request never mentioned it because nobody ever does.","fixes":["Put kboateng into Sales Mailbox - Send As"],"urgency":2,"claimed":3,"kb":{"title":"Full Access and Send As are two permissions","resolution":["Grant Full Access on the mailbox. That is what lets somebody open it, read it and file things in it.","Then ask the question the request did not: will they be REPLYING from it? If anybody answers yes, they need Send As as well.","Add the account to the Send As group for that mailbox. On this estate that is where the permission lives.","Say both out loud on the ticket. The next person to read the request will read it exactly as literally as you did."]}},
  {"id":"ticket:licence-exhausted","title":"New starter cannot open the accounts package","body":"Rob started this morning. Everything works except the one program his entire job is, which opens, thinks about it, and says it cannot obtain a licence. His manager has been standing behind him for twenty minutes saying it was fine last time.","reporter":"Rob Tulliver","reporterTitle":"Finance Assistant (first day)","archetype":"hidden_cause","cause":"Every seat in the pool is held, and one of them is held by an account that was disabled in April. Disabling somebody does not hand their licence back; nothing does, until a person does.","fixes":["Take the seat back off the leaver, then give it to the new starter"],"urgency":3,"claimed":3,"kb":{"title":"No free seats, and the man who left in April","resolution":["Read the pool before you touch an account: how many seats exist and how many are free. Nought free is not a fault, it is arithmetic.","Find who is holding them. Sort the directory by the licence flag and look for accounts that are disabled - a leaver holding a seat is the classic, and there is almost always one.","Take the seat back off the leaver. Then assign it to the new starter. That order, because the second one is refused until the first has happened.","Raise the underlying problem separately: the leavers process should be reclaiming these, and it is not, and that is a ticket about a process rather than about a person."]}},
  {"id":"ticket:vpn-cert-expired","title":"Nobody working from home can connect","body":"Nina is at the depot and cannot get in. Neither, in the last eleven minutes, can anybody else who is not in this building. The client says the connection could not be verified, which is the politest possible way of saying the certificate ran out this morning.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"flood","cause":"The certificate the VPN concentrator presents expired this morning. The service is running and rejecting every connection, politely.","fixes":["renewcert vpn - a new certificate, not a restart"],"urgency":3,"claimed":3,"kb":{"title":"Running perfectly and refusing everybody","resolution":["Check the service is actually running before you believe anybody. In this case it will be, and that is the diagnosis.","Read the certificate expiry. \"Could not be verified\", \"not trusted\" and \"the name on the certificate does not match\" are three different messages and only one of them is this.","Renew the certificate. Do NOT restart the service first: it comes back with the same expired certificate and forty more people notice.","Raise the renewal date somewhere a human will see it. Certificates are the only fault in this building that sends you a warning and picks the date itself."]}},
  {"id":"ticket:vpn-cert-dup-ada","title":"VPN not working from home (URGENT)","body":"Ada is at home with the good coffee and cannot reach anything. She has restarted her laptop, her router and, at one point, her phone, and would like it noted that she did all of that before contacting anybody, which is true and which she will mention again.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"flood","cause":"The same expired certificate as everybody else this morning.","fixes":["Attach it to the incident, fix that, and tell her with the rest"],"urgency":3,"claimed":3,"kb":{"title":"Running perfectly and refusing everybody","resolution":["Check the service is actually running before you believe anybody. In this case it will be, and that is the diagnosis.","Read the certificate expiry. \"Could not be verified\", \"not trusted\" and \"the name on the certificate does not match\" are three different messages and only one of them is this.","Renew the certificate. Do NOT restart the service first: it comes back with the same expired certificate and forty more people notice.","Raise the renewal date somewhere a human will see it. Certificates are the only fault in this building that sends you a warning and picks the date itself."]}},
  {"id":"ticket:vpn-cert-dup-gary","title":"Remote access has stopped working again","body":"Gary is working from home on the payroll run and the connection will not come up. He suspects it is the same thing as his password, on the grounds that both of them are computers and both of them have now let him down in the same fortnight.","reporter":"Gary Poole","reporterTitle":"Payroll Clerk","archetype":"flood","cause":"The same expired certificate as everybody else this morning.","fixes":["Attach it to the incident, fix that, and tell him with the rest"],"urgency":2,"claimed":3,"kb":{"title":"Running perfectly and refusing everybody","resolution":["Check the service is actually running before you believe anybody. In this case it will be, and that is the diagnosis.","Read the certificate expiry. \"Could not be verified\", \"not trusted\" and \"the name on the certificate does not match\" are three different messages and only one of them is this.","Renew the certificate. Do NOT restart the service first: it comes back with the same expired certificate and forty more people notice.","Raise the renewal date somewhere a human will see it. Certificates are the only fault in this building that sends you a warning and picks the date itself."]}},
  {"id":"ticket:share-maintenance","title":"The common drive has gone","body":"Bev cannot reach the visitor list, which lives on the common drive, which has not existed since nine o'clock. There is a mail in your own inbox saying the drive would be unavailable from nine until eleven. It is now well past eleven, which is the part of this that is actually a fault.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"flood","cause":"The announced maintenance window took the file sharing service down at nine and nobody started it again when the window closed.","fixes":["Start file sharing again - the window closed an hour ago"],"urgency":3,"claimed":3,"kb":{"title":"It was announced, and it is still broken","resolution":["Read your own inbox first. If there is a window, note when it OPENS and when it CLOSES; the second one is the number that matters.","Inside the window: attach the reports to one parent incident, reply with the announcement and the time it ends, and stop there.","Past the closing time: it is a fault, whatever the mail said. Check the service actually came back and start it if it did not.","Close the duplicates with the parent so every reporter gets the same sentence at the same minute. Forty different explanations of one outage is how a service desk loses an argument it was winning."]}},
  {"id":"ticket:share-dup-terry","title":"All my files have been deleted","body":"Terry reports that his files have been deleted. On being asked which files, he says all of them. On being asked where they were, he says on the drive. The drive is not there, so from where he is sitting this is an accurate report of a catastrophe.","reporter":"Terry Blunt","reporterTitle":"Estimating","archetype":"flood","cause":"The same maintenance window as everybody else, seen from a desk where a missing drive and a deleted file look identical.","fixes":["Attach it to the drive incident and close it with that one"],"urgency":2,"claimed":3,"kb":{"title":"It was announced, and it is still broken","resolution":["Read your own inbox first. If there is a window, note when it OPENS and when it CLOSES; the second one is the number that matters.","Inside the window: attach the reports to one parent incident, reply with the announcement and the time it ends, and stop there.","Past the closing time: it is a fault, whatever the mail said. Check the service actually came back and start it if it did not.","Close the duplicates with the parent so every reporter gets the same sentence at the same minute. Forty different explanations of one outage is how a service desk loses an argument it was winning."]}},
  {"id":"ticket:vacuum-tuesday","title":"Warehouse printer was dead again when I came in","body":"Owen reports that the Ajax was off when he opened up. Not jammed, not out of paper: off, with the standby light out, the way a thing is off when it has no electricity. He has plugged it back in himself twice this month and it did not seem worth a ticket either time.","reporter":"Owen Pryce","reporterTitle":"Logistics, late shift","archetype":"recurring_arc","cause":"The printer lost power at four minutes to five yesterday evening. Nothing on the box did it, which is the only interesting thing about it so far.","fixes":["Bring the Ajax back up from the hardware panel on PRINT-02"],"urgency":2,"claimed":2,"kb":{"title":"The same fault, the same evening, every week","resolution":["Stop fixing it. Open the Event Viewer for the machine and write down the times it went down, not just the dates.","Compare them. Two outages at the same minute on different days is not a coincidence and is not a hardware fault; it is somebody's round.","Work out whose round. Cleaning, security, deliveries and the people who service the vending machine all have timetables, and Facilities know all of them.","Fix it where the cause is: a note by the socket, a socket cover, or a different socket. Then write down what it was, because the next person to see this will not have the timestamps."]}},
  {"id":"ticket:vacuum-thursday","title":"The warehouse printer is off AGAIN","body":"Owen, again, in capitals, at ten past eight. Same printer, same dead standby light, same morning of the week it was on Tuesday. He would like somebody to work out what is doing it rather than turn it on, and he is right, and he has been right for about a month.","reporter":"Owen Pryce","reporterTitle":"Logistics, late shift","archetype":"recurring_arc","cause":"The cleaner's trolley needs a socket on Tuesday and Thursday evenings, and the only one in that corridor has the warehouse print box in it. Nobody has ever told her, because nobody has ever looked at two timestamps together.","fixes":["Power it back up, then get Vic in Facilities to put a note on that socket"],"urgency":2,"claimed":3,"kb":{"title":"The same fault, the same evening, every week","resolution":["Stop fixing it. Open the Event Viewer for the machine and write down the times it went down, not just the dates.","Compare them. Two outages at the same minute on different days is not a coincidence and is not a hardware fault; it is somebody's round.","Work out whose round. Cleaning, security, deliveries and the people who service the vending machine all have timetables, and Facilities know all of them.","Fix it where the cause is: a note by the socket, a socket cover, or a different socket. Then write down what it was, because the next person to see this will not have the timestamps."]}},
  {"id":"ticket:flat-mouse","title":"My computer has frozen completely","body":"Ada reports that the machine has locked up entirely: nothing moves, nothing clicks, and the pointer is exactly where she left it after lunch. The screen is showing a low-battery notice for a wireless mouse, which she has read, and which she believes is a separate issue she will raise later.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"read_the_screen","cause":"The mouse batteries are flat. The machine is fine and has been fine throughout, which is what makes \"frozen\" such a good word for it.","fixes":["Put batteries in the mouse from the hardware panel"],"urgency":1,"claimed":3,"kb":{"title":"The error message is usually the answer","resolution":["Ask the reporter to read the message out word for word, including the part that looks like small print.","Read your own tools the same way: a refusal here always says what it refused and why, and the reason line is the diagnosis.","Write the answer into the ticket, not just into the fix."]}},
  {"id":"ticket:coverup-backup","title":"Backup light has gone red and I have not touched anything","body":"Marcus reports a red light in the corner of his screen and is at pains to say the machine did it by itself, over the weekend, while he was not here. He mentions unprompted that the fan had been very loud on Friday and that he had not done anything about that either.","reporter":"Marcus Kelp","reporterTitle":"Management Accountant","archetype":"hidden_cause","cause":"The backup agent was stopped from the console on ACCTS-03, on a morning the directory says he was signed in, about four minutes after the fan got loud.","fixes":["restart the backup agent on ACCTS-03","Start it from the services panel while he watches"],"urgency":2,"claimed":2,"kb":{"title":"The machine wrote down what happened to it","resolution":["Open Event Viewer and pick the machine the reporter is actually on, not the one they said.","Filter to Error and Warning first. Information is where the truth lives, but Error is where the morning goes.","Read the TIMES, not just the messages. Two failures at the same minute on different days is a pattern, and a pattern has a cause with a timetable - a backup, a shift change, a cleaner and a socket.","Put what you found on the ticket in the words the log used, event id and all. It is the difference between a fix and a diagnosis."]}},
  {"id":"ticket:hr-report-macro","title":"Headcount report has not run since March - needed by 15:00","body":"Yolanda needs the headcount report for a board pack at three. The report has not run since March. She has known since March. Nobody raised it in March because everybody has been doing it by hand since March, quietly, at home, on a Sunday.","reporter":"Yolanda Reece","reporterTitle":"HR Manager","archetype":"deadline_absurdity","cause":"The scheduled reports service on the file server has been stopped since a maintenance window in March, and the report is a thing it runs.","fixes":["Start the scheduled reports service and let it catch up","Try the obvious thing, then send it up with the date it actually broke on"],"urgency":1,"claimed":3,"kb":{"title":"Broken since March, needed by three","resolution":["Find out when it actually broke, and put that date on the ticket in the first work note. It is the most useful sentence on the record.","Check whether it is fixable from here. A scheduled job that has been stopped since a maintenance window usually just needs starting.","If it is not - if it needs rewriting, or data nobody has - hand it on with the date it broke and the deadline side by side, and say plainly which of the two you can meet.","Either way, tell the requester what is possible before three, not at three. The deadline is theirs; the surprise does not have to be."]}},
  {"id":"ticket:phishing-report","title":"Probably nothing, but this email looks wrong to me","body":"Dennis has forwarded a mail asking him to re-enter his password because of \"unusual activity\". It is from a domain one letter off ours. He has not clicked it, has told the two people either side of him not to click it, and is apologising for wasting your time.","reporter":"Dennis Hoyle","reporterTitle":"Marketing","archetype":"hidden_cause","cause":"A lookalike domain, and a quarantine rule somebody wrote in March, tested once and never switched on because switching it on was a change and a change needed a form.","fixes":["Switch the quarantine rule on, then tell him he did the right thing"],"urgency":3,"claimed":2,"kb":{"title":"Somebody reported a suspicious mail. Reward that.","resolution":["Do not click the link. Not to check, not in a private window, not on the spare machine. There is nothing at the other end you need.","Verify it from the headers and the sender domain: a lookalike domain, a reply-to that does not match, an urgency that does not fit the sender.","Quarantine the sender - the transport rule is where that is done - and check whether it went to anybody else.","REPLY TO THE REPORTER, in words, saying they were right to send it. This is the step people skip and it is the one that pays."]}},
  {"id":"ticket:saved-into-temp","title":"All my work from yesterday has gone","body":"Priya opened the Holloway statement out of a mail yesterday afternoon, spent two hours going through it with the supplier on the phone, and pressed Save about nine times. This morning it is not in My Documents, it is not in the mail, and she would like somebody to tell her the machine has not thrown away an afternoon. She is quite clear that she saved it. She saved it.","reporter":"Priya Raval","reporterTitle":"Accounts Payable","archetype":"hidden_cause","cause":"The mail client wrote the attachment into C:\\WINDOWS\\TEMP to open it, and Save wrote back to where the file was opened from. Nine times. Nothing was lost, nothing is broken, and the machine would have thrown it away at the next clear-out without ever mentioning it.","fixes":["Move it out of TEMP into her own documents"],"urgency":2,"claimed":3,"kb":{"title":"The file has not gone anywhere. It is in TEMP.","resolution":["Ask what they OPENED it from, not where they saved it. \"Out of an email\" and \"off the P: drive\" are two different answers with two different directories behind them.","Look in the temp directory on their box before you look anywhere else: \"dir \\\\<host>\\C$\\WINDOWS\\TEMP\". The file will be there, under whatever the sender called it, stamped the minute they last pressed Save.","Prove it is the right one before you touch it - \"type\" the file and read a line of it back to them. A temp directory has more than one thing in it and none of them is labelled.","Move it where they thought it was: \"move <file> <directory>\". Move rather than copy, because two copies of a spreadsheet is a fortnight of somebody editing the wrong one."]}},
  {"id":"ticket:disk-full","title":"WHOUSE-01 says there is not enough space and it is lying","body":"Hilda reports that the warehouse machine will not save the booking-in sheet, will not print it, and puts up a box about disk space every time she tries. She points out that she has saved four things on that computer in her entire life, that the last one was a Christmas rota, and that it therefore cannot possibly be full of hers.","reporter":"Hilda Marsh","reporterTitle":"Warehouse Supervisor","archetype":"hidden_cause","cause":"The pallet scanner has written a monthly export into C:\\SCANNER\\EXPORT since 1997 and deleted none of them. Twelve of them are three hundred megabytes on a drive that had three left, and every one of them was uploaded to head office the night it was written.","fixes":["Empty the scanner exports, which went to head office in 1997"],"urgency":3,"claimed":2,"kb":{"title":"One directory has eaten the drive","resolution":["Get the free space first: the last line of any listing on that drive says it. \"dir \\\\<host>\\C$\" - the footer is the fact, and the reporter's description is not.","Walk the drive for the pile: \"tree \\\\<host>\\C$\" for the shape of it, then \"dir\" on anything that looks like it belongs to a program rather than to a person. The footer of each listing reports what that directory holds; one of them will be an order of magnitude larger than the space you are short of.","Read the software's own configuration before you delete a byte. It says where it writes, how often, and what happens to the output afterwards - and \"uploaded the same night\" is the sentence that makes what is left a second copy.","Empty the one that is a second copy, and only that one: \"purge <directory>\". The data directory next door with the same software's name on it is usually the only copy of something the business runs on, and this desk does not delete those."]}},
  {"id":"ticket:vpn-month-end","title":"Need VPN before tomorrow please - working from home for month-end","body":"Raised at 16:55. Marcus is doing month-end from home tomorrow and has just tried the remote client for the first time, which told him he is not permitted. He has added that he is not in tomorrow until half eight and would rather not ring anybody at half eight.","reporter":"Marcus Kelp","reporterTitle":"Management Accountant","archetype":"hidden_cause","cause":"Nothing is broken. He is not a member of VPN Users, has never been a member of VPN Users, and has never needed to be until this week.","fixes":["Put the account into VPN Users in Active Dictionary"],"urgency":2,"claimed":3,"kb":{"title":"The request that arrives five minutes before you go home","resolution":["Read the deadline rather than the arrival. Both clocks on a ticket are counted in working minutes, so five minutes of tonight plus fifty-five of tomorrow is an hour, and the hour runs out at 09:55 rather than at 17:55.","Decide whether it is genuinely tonight. Almost none of them are: the test is whether somebody cannot work tomorrow morning, not whether they said it was urgent at five to five.","If it is not, leave it, and leave it deliberately - untriaged, in the queue, with the deadline the world gave it. A ticket carried overnight is not a ticket ignored.","If it is, say so on the ticket before you go. A first line written tonight stops the response clock tonight, and it is the only thing you can do at five to five that is worth anything tomorrow."]}},
  {"id":"ticket:gary-restart","title":"Restart request - PAYROLL-04 (raised as asked)","body":"Gary has raised this because he was asked to. The machine has been asking him to restart to finish installing updates since before his fortnight off; he has been clicking Later ever since, because payroll is open on that machine most of the day. He has listed the two half-hours it is not.","reporter":"Gary Poole","reporterTitle":"Payroll Clerk","archetype":"read_the_screen","cause":"Updates were staged a fortnight ago and want the machine to go round once. Nothing else is wrong with it, and nothing else will be until somebody restarts it.","fixes":["Restart PAYROLL-04 from Remote Assist"],"urgency":1,"claimed":1,"kb":{"title":"It has been asking to restart since last week","resolution":["Check the machine actually has updates staged before you restart anything. A prompt somebody half-remembers is not evidence, and a restart that fixes nothing has still cost them their afternoon.","Ask when they are not in a call. This is the entire job on a sales floor and it is not a courtesy: a machine restarted mid-call is a ticket about you rather than about updates.","Restart it from Remote Assist. The staged updates finish on the way back up and the prompt is gone.","Ask for a ticket if there was not one. It takes them a minute, it takes you none, and it is the only record that the work happened at all."]}},
  {"id":"ticket:bev-vpn-request","title":"VPN for working from home (raised from a channel request)","body":"Bev is on reception and is working from home the day they take the boiler out. She has never used the remote client and it will not have her. She asked in mail, in chat and in the helpdesk room, all within a couple of minutes, because she was not sure which one anybody actually reads - and this ticket exists because somebody turned the asking into one.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"hidden_cause","cause":"Nothing is broken. Bev is not a member of VPN Users, has never been a member of VPN Users, and has never needed to be until this week.","fixes":["Put the account into VPN Users in Active Dictionary"],"urgency":1,"claimed":2,"kb":{"title":"The request that arrives five minutes before you go home","resolution":["Read the deadline rather than the arrival. Both clocks on a ticket are counted in working minutes, so five minutes of tonight plus fifty-five of tomorrow is an hour, and the hour runs out at 09:55 rather than at 17:55.","Decide whether it is genuinely tonight. Almost none of them are: the test is whether somebody cannot work tomorrow morning, not whether they said it was urgent at five to five.","If it is not, leave it, and leave it deliberately - untriaged, in the queue, with the deadline the world gave it. A ticket carried overnight is not a ticket ignored.","If it is, say so on the ticket before you go. A first line written tonight stops the response clock tonight, and it is the only thing you can do at five to five that is worth anything tomorrow."]}},
  {"id":"ticket:pool-sales-restart","title":"Box about restarting - can somebody make it go away","body":"Ada has a dialog that says the updates are downloaded and it needs to restart to finish. She has read it, she does not disagree with it, and she has pressed Later every morning since the week before last because she is on the phone every morning since the week before last. She is free between twelve and half past.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"read_the_screen","cause":"Updates were staged a fortnight ago and are waiting for the machine to go round once. Nothing else is wrong with SALES-02 and nothing else will be.","fixes":["Restart SALES-02 from Remote Assist, between twelve and half past"],"urgency":1,"claimed":1,"kb":{"title":"It has been asking to restart since last week","resolution":["Check the machine actually has updates staged before you restart anything. A prompt somebody half-remembers is not evidence, and a restart that fixes nothing has still cost them their afternoon.","Ask when they are not in a call. This is the entire job on a sales floor and it is not a courtesy: a machine restarted mid-call is a ticket about you rather than about updates.","Restart it from Remote Assist. The staged updates finish on the way back up and the prompt is gone.","Ask for a ticket if there was not one. It takes them a minute, it takes you none, and it is the only record that the work happened at all."]}},
  {"id":"ticket:pool-sales-spooler","title":"The print server is down (for me)","body":"Ada reports that nothing she prints arrives and that the print server must therefore be down. She has watched Kwame print the same document from the next desk, on the same printer, and considers that a separate and rather suspicious matter. Her jobs vanish without an error of any kind.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"hidden_cause","cause":"The Print Spooler service on SALES-02 is stopped. A job printed from that machine is handed to the spooler on that machine before it goes anywhere, so it never leaves the desk, and nothing on the print server ever hears about it.","fixes":["Start the Print Spooler service on SALES-02"],"urgency":2,"claimed":3,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-payroll-clock","title":"It keeps throwing me out and the timesheet says I was early","body":"Gary is being signed out of things he has only just signed into, and the timesheet portal has recorded him as arriving at twenty past seven, which he would like to correct on the record. He has also noticed that the clock in the corner of his screen disagrees with the clock on the wall, and has been setting it back by hand every few days without mentioning it to anybody.","reporter":"Gary Poole","reporterTitle":"Payroll Clerk","archetype":"hidden_cause","cause":"The Time Service on PAYROLL-04 is stopped, so nothing has been correcting that machine against DC-01 and the clock on the board has drifted. The directory refuses a logon timestamped too far from its own time, which is what every one of his symptoms actually is.","fixes":["Start the Time Service on PAYROLL-04 and let it pull the clock back to the domain"],"urgency":3,"claimed":2,"kb":{"title":"A domain has one clock, and one machine has stopped agreeing","resolution":["Compare the time on the machine with the time on DC-01 before you believe any part of the reporter's description. Minutes matter here; a machine three minutes out has no symptoms and a machine ten minutes out cannot log on.","Check the Time Service on the box - it is Automatic on every machine here - and start it if it has stopped. That is what has let the clock drift; the drift itself is the hardware doing what cheap hardware does when nobody is correcting it.","Get the reporter to sign out and back in once the service is running, because the credential they are holding was issued against the wrong time and will keep being refused until it is reissued.","Say plainly on the ticket which machine was wrong. Every symptom of this points at the server, and the server was right the whole time."]}},
  {"id":"ticket:pool-payroll-share","title":"Common drive says access is denied","body":"Gary has been asked to put the quarter's figures on the common drive like everybody else. The common drive says access is denied. He has been emailing them to people for eleven years and would be perfectly happy to carry on doing that.","reporter":"Gary Poole","reporterTitle":"Payroll Clerk","archetype":"read_the_screen","cause":"Nobody has ever put his account on the common drive. It is not a fault and nothing has changed: payroll kept its own figures on its own machine, so the grant was never needed and was therefore never made.","fixes":["Put gpoole on the common drive's access list"],"urgency":2,"claimed":2,"kb":{"title":"A drive that has never worked, for exactly one person","resolution":["Ask who else cannot reach it. One person is an access list; the whole floor is the server, and the two have nothing in common but the sentence the reporter uses.","Read the share's own access list rather than the group memberships. A share is granted per account here, so somebody can be in every group in the directory and still not be on it.","Find out whether they have EVER had it. \"It has stopped working\" and \"I have never been able to\" are the same sentence from a user and two different jobs for you.","Grant the access, and put on the ticket that it was never there. A ticket that reads \"restored access\" invites the next person to go looking for what removed it."]}},
  {"id":"ticket:pool-hercules-dead","title":"Hercules is completely dead - no lights, nothing","body":"Nina reports that the Hercules has no lights on it at all. Not flashing, not humming: dead, the way a thing is dead when it is not plugged into anything. The whole floor prints through it and the whole floor has already been told.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"read_the_screen","cause":"The printer is off at the switch on the back of it, which is the switch nobody looks at because nobody has ever touched it on purpose.","fixes":["Power the Hercules back up from the hardware panel"],"urgency":3,"claimed":3,"kb":{"title":"Have you tried turning it off and on again (and why it works)","resolution":["Ask what is running on it before you restart anything shared. The print server in this building also carries the VPN.","Restart the smallest thing that could be at fault: the service before the machine, the machine before the floor.","Check what was already written down - queues, settings, files - because a restart hands all of it straight back to you.","If the same box wedges every Friday, stop restarting it and start reading its event log. That is a standing appointment, not support."]}},
  {"id":"ticket:pool-despatch-lpd","title":"Delivery notes out of the old system are not coming out","body":"Nina reports that everything she prints out of Windows is fine and everything the old delivery system prints is not. No error, no queue, nothing in the pending list - the notes simply do not appear. She has printed the same note out of Windows to prove the printer works, which it does, which she says makes it worse.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"hidden_cause","cause":"The TCP/IP Print Server service on PRINT-01 is stopped. Windows machines hand their jobs to the spooler directly and are unaffected; the old delivery system is not a Windows machine and prints the only way it knows, which is to that service, which is not listening.","fixes":["Start the TCP/IP Print Server service on PRINT-01"],"urgency":3,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-reception-locked","title":"It will not take my password and there are people in reception","body":"Bev cannot get in. She has typed the same password she has typed since March, several times, with increasing conviction, and the box has said no to all of them. There are two visitors standing in front of her and the sign-in book is in a drawer she needs the computer to know she is allowed to open.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"read_the_screen","cause":"The lockout counter tripped after five attempts, all of them typed in capitals, on the reception keyboard whose Caps Lock light stopped working before the merger.","fixes":["Unlock btannock in Active Dictionary"],"urgency":2,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:pool-reception-badges","title":"Visitor badges will not print and the auditors are in at two","body":"Bev cannot print the visitor badges. The badge template has not printed since the autumn, she has been writing them out by hand since the autumn, and the auditors arriving at two are the first visitors in four months who will look at one. The print server has been asking to restart to finish installing updates since September.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"deadline_absurdity","cause":"PRINT-01 has been carrying staged updates since September and the badge template is one of the things waiting on them. The restart is two minutes; what makes it a decision is that the same box carries the VPN, so doing it now takes the depot off the network for those two minutes and doing it at one o'clock does not.","fixes":["Restart PRINT-01, having told the depot which two minutes it is"],"urgency":2,"claimed":3,"kb":{"title":"VPN concentrator (DRAFT - do not follow step 2 yet)","resolution":["Check the concentrator is actually running: \"services PRINT-01\".","Reboot the print server. [Editor: no. Do not do this in working hours. Half the building is printing through this box and this step was written by somebody whose notice period had already started.]","Restart the concentrator service on its own, which is what step 2 was trying to say."]}},
  {"id":"ticket:pool-despatch-queue","title":"Ajax has twelve things queued and is printing none of them","body":"Owen reports the despatch printer sitting with a stack of jobs on it and nothing coming out. He has read the queue out over the phone: eleven delivery notes, all the same size, and one thing at the front of it that is five hundred kilobytes and is not a delivery note.","reporter":"Owen Pryce","reporterTitle":"Logistics, late shift","archetype":"read_the_screen","cause":"Somebody sent a spreadsheet to the despatch printer at four minutes past six. It is at the front of the queue, the Ajax has been chewing on page one of it ever since, and the eleven delivery notes behind it are waiting their turn politely.","fixes":["Empty the queue on the Ajax and tell despatch to send the notes again"],"urgency":2,"claimed":3,"kb":{"title":"The print spooler, and why the queue goes first","resolution":["Look at the queue: \"queue <printer>\" says how many jobs are stacked up behind whatever jammed, and what the spooler reports.","Those jobs are files, and files are in a directory. \"dir \\\\PRINT-01\\C$\\WINDOWS\\SYSTEM32\\SPOOL\\PRINTERS\" is the same backlog with a date and a size on every line of it - and four files of exactly the same size are four copies of the same delivery note, which is the thing the reporter has not told you.","STOP THE SPOOLER, then empty the queue. The queued jobs are files on disk and the running service has them open, which is exactly when deleting them fails. On this estate those are one control - \"clearqueue <printer>\", or the hardware panel in Remote Assist - and it stops the service before it drops anything.","Start the spooler again: \"restart spooler\", or its taskbar entry on the print server. It is deliberately left stopped until you do, because that is the third step and it is yours."]}},
  {"id":"ticket:pool-despatch-expired","title":"Message about my password at six this morning","body":"Owen has written down what the box said, because he has learned that is the useful thing to do: \"Your password has expired. Click Continue to change it.\" He clicked Continue, was asked for the old password and two copies of a new one, and got as far as discovering that the new one has to be different from the old one.","reporter":"Owen Pryce","reporterTitle":"Logistics, late shift","archetype":"read_the_screen","cause":"The password policy expired his credential overnight. The account is not locked and not disabled: it is out of date, which is the third of the three and the only one a reset is the answer to.","fixes":["Reset opryce in Active Dictionary and tell him what it will ask him next"],"urgency":2,"claimed":2,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:pool-facilities-disabled","title":"The computer says I do not work here","body":"Vic has read the message out and written it down: \"Your account has been disabled. Please see your system administrator.\" He would like somebody to establish whether he still works here before he goes and unlocks the second floor, because if he does not, he would rather not have the keys.","reporter":"Vic Ndlovu","reporterTitle":"Facilities Supervisor","archetype":"read_the_screen","cause":"Facilities came off the staff payroll and onto a contract at the end of the quarter, and the leavers run reads the payroll list. It did exactly what it is written to do to somebody who is still in the building five days a week.","fixes":["Switch vndlovu back on in Active Dictionary"],"urgency":2,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:pool-accounts-updates","title":"Little shield thing in the corner, probably nothing","body":"Priya mentions, at the end of a call about something else, that the update icon on ACCTS-01 has a cross through it and has had for as long as she can remember. She says the machine is otherwise perfectly happy and she does not want to make a fuss about an icon.","reporter":"Priya Raval","reporterTitle":"Accounts Payable","archetype":"hidden_cause","cause":"Automatic Updates on ACCTS-01 is set to Disabled, so nothing has started it since whoever set it that way - and nothing ever will, including a reboot. The machine has been quietly out of date for as long as the icon has had a cross through it.","fixes":["Set Automatic Updates back to Automatic (Delayed Start) on ACCTS-01, then start it"],"urgency":3,"claimed":1,"kb":{"title":"Disabled is not stopped, and starting it is refused for a reason","resolution":["Read the startup type before you press anything. Disabled and stopped look identical to Manual and stopped in the status column, and they are two different jobs.","Find out WHO disabled it and why, if you can. Three services on every box in this building are Disabled deliberately, and re-enabling one of those is undoing somebody's decision rather than fixing a fault.","Set the startup type back to what the box is meant to run it as - Automatic for most, Automatic (Delayed Start) for the update service, Manual for the ones that are asked for.","THEN start it. Setting the startup type does not start anything: it tells the machine what to do at the next boot, and the service is still sitting there stopped until somebody starts it."]}},
  {"id":"ticket:pool-accounts-drives","title":"All my drives have red crosses on them","body":"Priya has three mapped drives and all three have gone at once. She has double-clicked each of them and written down what came back: \"The network path was not found.\" She points out that all three are on different servers, which she thinks makes it worse and which actually makes it simpler.","reporter":"Priya Raval","reporterTitle":"Accounts Payable","archetype":"read_the_screen","cause":"The Workstation service on ACCTS-01 is stopped. That service IS the machine's ability to reach a network share at all, so every mapped drive on it fails in the same second and every server it names is fine.","fixes":["Start the Workstation service on ACCTS-01"],"urgency":2,"claimed":3,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-estimating-rotated","title":"Everything is upside down","body":"Terry cleaned his keyboard this morning, which he would like noted as a thing he did for the good of the department, and his screen is now upside down. He has not touched anything since and is describing it to you while reading it upside down.","reporter":"Terry Blunt","reporterTitle":"Estimating","archetype":"read_the_screen","cause":"A wipe across a keyboard is Control, Alt and an arrow key held down together for as long as it takes to wipe a keyboard. The screen did exactly what that means.","fixes":["Put EST-03 back to nought degrees"],"urgency":1,"claimed":3,"kb":{"title":"The screen that went sideways on its own","resolution":["Confirm what the reporter is seeing: the picture is turned, the mouse still moves the way it always did, and nothing else is wrong.","Set the rotation back to 0 - \"rotate <host> 0\" in the terminal, or the control on the remote screen in Remote Assist. Both do the same thing to the same machine.","Tell the reporter, out loud, that nothing was accessed and their password is fine. They have spent the morning assuming otherwise.","Mention the shortcut - Control, Alt and an arrow key - so the next person who leans on their keyboard knows what they have done."]}},
  {"id":"ticket:pool-estimating-tender","title":"Denby tender has gone and it goes at four","body":"Terry has spent three days on the revised Denby tender and it is not in his documents. It goes to the client at four. The version that IS in his documents is last week's, with the steel figure they have already been beaten on, and he says he would rather send nothing than send that.","reporter":"Terry Blunt","reporterTitle":"Estimating","archetype":"deadline_absurdity","cause":"The quantity surveyor mailed him rev 2 and he has worked in it out of the mail ever since. The mail client wrote it into C:\\WINDOWS\\TEMP to open it, and Save has gone back there every time. Nothing is lost, nothing is broken, and the machine would have thrown it away at the next clear-out without mentioning it to anybody.","fixes":["Move rev 2 out of TEMP into his own documents, and read the top of it back to him before he sends it"],"urgency":3,"claimed":3,"kb":{"title":"The file has not gone anywhere. It is in TEMP.","resolution":["Ask what they OPENED it from, not where they saved it. \"Out of an email\" and \"off the P: drive\" are two different answers with two different directories behind them.","Look in the temp directory on their box before you look anywhere else: \"dir \\\\<host>\\C$\\WINDOWS\\TEMP\". The file will be there, under whatever the sender called it, stamped the minute they last pressed Save.","Prove it is the right one before you touch it - \"type\" the file and read a line of it back to them. A temp directory has more than one thing in it and none of them is labelled.","Move it where they thought it was: \"move <file> <directory>\". Move rather than copy, because two copies of a spreadsheet is a fortnight of somebody editing the wrong one."]}},
  {"id":"ticket:pool-portal-cert","title":"Timesheet site is throwing a warning at everybody","body":"Marcus reports a warning page in front of the timesheet portal saying the site cannot be trusted. He has clicked through it, because everybody clicks through it, and would like somebody to know that the whole of Accounts has now been trained to click through a security warning to fill in a timesheet.","reporter":"Marcus Kelp","reporterTitle":"Management Accountant","archetype":"hidden_cause","cause":"The certificate on the intranet site expired on a Sunday. Nothing broke, nothing crashed and nothing sent anybody a warning beforehand - a certificate has a date on it, the date passed, and every browser in the building started saying so at nine on Monday.","fixes":["Issue a new certificate for the portal on INTRA-01"],"urgency":3,"claimed":1,"kb":{"title":"Running perfectly and refusing everybody","resolution":["Check the service is actually running before you believe anybody. In this case it will be, and that is the diagnosis.","Read the certificate expiry. \"Could not be verified\", \"not trusted\" and \"the name on the certificate does not match\" are three different messages and only one of them is this.","Renew the certificate. Do NOT restart the service first: it comes back with the same expired certificate and forty more people notice.","Raise the renewal date somewhere a human will see it. Certificates are the only fault in this building that sends you a warning and picks the date itself."]}},
  {"id":"ticket:pool-accounts-browse","title":"Network Neighbourhood is empty - has the network gone","body":"Marcus opened Network Neighbourhood to find a machine whose name he half remembers and it is empty. Not an error: empty. His mail is fine, his drives are fine and he can print, all of which he offers as evidence that something serious has happened to the network.","reporter":"Marcus Kelp","reporterTitle":"Management Accountant","archetype":"read_the_screen","cause":"The Computer Browser service on ACCTS-03 is stopped. That service is the only thing that collects the list of machines Network Neighbourhood draws, so the list is empty - and everything that reaches a machine by name rather than by browsing carries on working perfectly.","fixes":["Start the Computer Browser service on ACCTS-03"],"urgency":1,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-warehouse-schedule","title":"Head office says they have not had the pallet file","body":"Hilda has been rung by somebody at head office who wants last month's pallet export and has been waiting for it since the first. She has never sent it in her life - the machine in the corner sends it at midnight and always has - and she would like to know why she is the one being rung about it.","reporter":"Hilda Marsh","reporterTitle":"Warehouse Supervisor","archetype":"hidden_cause","cause":"The Task Scheduler service on WHOUSE-01 is stopped. The pallet scanner does not run its own export - it asks the scheduler to run it monthly, and the scheduler has not been there to be asked. Nothing failed and nothing wrote an error, because nothing ever started.","fixes":["Start the Task Scheduler service on WHOUSE-01"],"urgency":2,"claimed":1,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-warehouse-tablet","title":"Scanner in the cupboard has died","body":"Hilda reports the scanning tablet dark and unresponsive. The last thing on the screen, which she has written down, was a box about the battery being low. She read it, agreed with it, and put the tablet back in the cupboard.","reporter":"Hilda Marsh","reporterTitle":"Warehouse Supervisor","archetype":"read_the_screen","cause":"The battery is flat. The tablet said so, in a box, before it went dark.","fixes":["Put a battery in the scanning tablet from the hardware panel"],"urgency":1,"claimed":2,"kb":{"title":"The error message is usually the answer","resolution":["Ask the reporter to read the message out word for word, including the part that looks like small print.","Read your own tools the same way: a refusal here always says what it refused and why, and the reason line is the diagnosis.","Write the answer into the ticket, not just into the fix."]}},
  {"id":"ticket:pool-sales-new-mfa","title":"The codes were on the agency phone and I have handed it back","body":"Kwame came through an agency for his first fortnight and has just been given a company handset. The authenticator was set up on the agency one, which he posted back on Friday in the envelope they provided, and he is apologising for this at some length.","reporter":"Kwame Boateng","reporterTitle":"Sales Executive","archetype":"hidden_cause","cause":"The second factor was bound to a handset that is now in the post to an agency. Nothing is broken; the binding is simply not there any more, and only a new enrolment puts one back.","fixes":["Prove who he is through a channel his account already has, then enrol the new handset with \"mfa kboateng\""],"urgency":2,"claimed":3,"kb":{"title":"A new phone, and an authenticator with nothing in it","resolution":["Read the account first. If the second factor is still enrolled, the problem is the app or the clock on the phone, not the account.","PROVE WHO YOU ARE TALKING TO before you enrol anything, and prove it with something the ACCOUNT has rather than something the caller can tell you. Four channels count on this estate: a callback to the number the directory already holds, the recovery code issued in the June envelope, an in-person check, or a recovery contact nominated in advance.","A payroll number, a hiring manager and a desk are NOT any of those. They are on a payslip, on the company website and on a seating plan. Somebody ringing to take an account off you will have all three, and will be apologetic about only having three.","Record which channel you used - \"verify callback <account>\", or the option in the conversation. \"Verified\" is not an answer to how, and how is what the incident report asks."]}},
  {"id":"ticket:pool-finance-sound","title":"No sound on FIN-02 - is that normal here?","body":"Rob has no sound at all and a red cross on the speaker in the corner. He is three weeks in and genuinely unsure whether this is a fault or simply how the machines are.","reporter":"Rob Tulliver","reporterTitle":"Finance Assistant (first day)","archetype":"read_the_screen","cause":"Windows Audio is stopped on FIN-02. The cross on the tray icon is the service being absent rather than a speaker or a lead being wrong.","fixes":["Start Windows Audio on FIN-02"],"urgency":1,"claimed":1,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-logistics-share","title":"The network is down - nobody can get at anything on FILES-01","body":"Nina got in at half seven and no mapped drive on the floor will open. She has established, before raising it, that the server is on, that she can ping it, and that the despatch notes she needs are on it. She has been doing this long enough to know that \"the network is down\" is not a diagnosis and has written it anyway, because it is what the floor is saying.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"hidden_cause","cause":"The Distributed File System service on FILES-01 is stopped, so the namespace the mapped drives resolve against answers nobody. The box is up, reachable and still serving the folders themselves - which is every mapped drive in the building failing for one reason nobody can see from a desk.","fixes":["Start Distributed File System on FILES-01"],"urgency":3,"claimed":3,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-marketing-trust","title":"\"The trust relationship between this workstation and the primary domain failed\"","body":"Dennis has photographed the message on his phone and attached it, which is more than most people do. He got in, could not log on, and borrowed the machine next to him - which let him on without complaint, so he has concluded the problem is his own machine and has apologised for it twice.","reporter":"Dennis Hoyle","reporterTitle":"Marketing","archetype":"hidden_cause","cause":"Net Logon is stopped on DC-01. It is the service that maintains the secure channel a domain member authenticates over, so a machine that needs to re-establish it gets told the trust relationship failed while a machine holding a live one carries on as though nothing is wrong.","fixes":["Start Net Logon on DC-01"],"urgency":3,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:pool-hr-print-group","title":"New starter cannot print anything - everything else works","body":"Yolanda has a starter on the second floor who can log on, open her mail and reach the shared drives, and whose print jobs vanish without a message. Yolanda has checked the starter form twice and everything on it was done.","reporter":"Yolanda Reece","reporterTitle":"HR Manager","archetype":"read_the_screen","cause":"The account is not in the print users group, so the print server accepts the connection and discards the job. Nothing on the starter form covers it, which is why every starter form is done correctly and this happens anyway.","fixes":["Add the account to the print users group"],"urgency":2,"claimed":2,"kb":{"title":"When the printer works for everybody except one person","resolution":["Ask who else is affected. One desk means permissions; the whole floor means the spooler.","Check the group in Active Dictionary against somebody who CAN print, rather than against what you expect to see.","Add the account back to Print Users.","Record it as what happened - \"re-added to Print Users\" - because the next person to read this ticket is three weeks away and it is you."]}},
  {"id":"ticket:pool-product-login-down","title":"A couple of customers say they cannot log in to the product","body":"Ada has had two emails this morning from customers saying the login page takes their password and then sits there. She has tried it herself on the demo account and it does the same. She has flagged it as a low priority because it is not stopping her doing anything.","reporter":"Ada Whitlock","reporterTitle":"Senior Account Manager","archetype":"read_the_screen","cause":"Whatever is wrong is on APP-01, which is a Linux box. The desk can prove it is on the network and can prove it cannot get into it: the Windows service tools stop at its operating system and ssh stops at the tier this account stands on. The article is written for an MSP helpdesk and the sentence is the same one either way - it is a server, it is production, and you are the helpdesk. What the desk owes it is a clean handoff with the time it started and what was ruled out, fast.","fixes":["Send it up with what you could and could not reach"],"urgency":3,"claimed":2,"kb":{"title":"It is a server / it is production and you are the helpdesk","resolution":["Recognise the boundary before you reach for a tool. A helpdesk contract covers workstations and user accounts; servers, and especially production, are not in it. Workstation credentials do not cross into the server tier, which is why the attempt is refused and not merely discouraged.","Do not try to work around it. On a Linux prod box a Windows tech has no console anyway, so the refusal is doubled - wrong contract and wrong toolset - and forcing it is how a Tier-1 tech ends up in an incident review.","Escalate it fast and clean: hand it to the team that owns the box - the customer's infrastructure team or the field engineers - with what is known and what was checked. A quick correct escalation beats a slow wrong fix, and on production it beats it by a lot."]}},
  {"id":"ticket:office-login-locked","title":"The front desk will not let anyone in","body":"Sharon reports that nobody can sign in at the front desk - the whole office shares the one login and it is refusing all of them this morning. She has read the message out: \"This account has been locked out.\" She is treating it as one person's problem, which is the one thing about a shared login it never is.","reporter":"Sharon Diss","reporterTitle":"Office Manager","archetype":"read_the_screen","cause":"The shared OFFICE login tripped its lockout after a run of failed attempts this morning - somebody at the desk typing it wrong on repeat - and nothing has cleared it since. One account, one lockout, the whole front office out.","fixes":["Unlock the OFFICE account in the directory","Unlock it with unlock office"],"urgency":3,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:accounts-package-down","title":"The accounts thing has stopped and I did not touch it","body":"Kev reports that the accounts package - the one he set up, on the server under his desk - has stopped, and is at pains to say the box did it by itself over the weekend. He mentions, unprompted, that the server fan has been getting louder and that he has not done anything about that either.","reporter":"Kevin Sump","reporterTitle":"Accounts, and computers, apparently","archetype":"hidden_cause","cause":"The accounts service on the server stopped - the event log has it going down at the weekend, on a box that is short of memory and hot with it. It starts straight back up; it will do it again until the box is looked at properly, which is a second-line job Kev keeps meaning to do.","fixes":["restart the accounts service on the server","Start it from the services panel while he watches"],"urgency":2,"claimed":3,"kb":{"title":"The machine wrote down what happened to it","resolution":["Open Event Viewer and pick the machine the reporter is actually on, not the one they said.","Filter to Error and Warning first. Information is where the truth lives, but Error is where the morning goes.","Read the TIMES, not just the messages. Two failures at the same minute on different days is a pattern, and a pattern has a cause with a timetable - a backup, a shift change, a cleaner and a socket.","Put what you found on the ticket in the words the log used, event id and all. It is the difference between a fix and a diagnosis."]}},
  {"id":"ticket:yard-printer-wedged","title":"Yard printer flashing and doing nothing","body":"Baz reports that the yard printer hums, flashes and prints nothing, and there are 19 jobs stacked behind whatever it is sulking about - most of them the same delivery note, sent again every time somebody walked back out and it still had not come out.","reporter":"Barry Coker","reporterTitle":"Yard","archetype":"hidden_cause","cause":"The spooler wedged on a malformed job and everything sent since has piled up behind it. Clearing the queue drops the job that jammed it; starting the spooler first only hands it back the thing that broke it.","fixes":["clearqueue on the yard printer, then restart the spooler"],"urgency":3,"claimed":3,"kb":{"title":"The print spooler, and why the queue goes first","resolution":["Look at the queue: \"queue <printer>\" says how many jobs are stacked up behind whatever jammed, and what the spooler reports.","Those jobs are files, and files are in a directory. \"dir \\\\PRINT-01\\C$\\WINDOWS\\SYSTEM32\\SPOOL\\PRINTERS\" is the same backlog with a date and a size on every line of it - and four files of exactly the same size are four copies of the same delivery note, which is the thing the reporter has not told you.","STOP THE SPOOLER, then empty the queue. The queued jobs are files on disk and the running service has them open, which is exactly when deleting them fails. On this estate those are one control - \"clearqueue <printer>\", or the hardware panel in Remote Assist - and it stops the service before it drops anything.","Start the spooler again: \"restart spooler\", or its taskbar entry on the print server. It is deliberately left stopped until you do, because that is the third step and it is yours."]}},
  {"id":"ticket:the-share-down","title":"Can't open the shared drive (probably the email thing?)","body":"Trev reports, from somewhere in the middle of the reply-all storm, that the shared drive has stopped answering. He thinks it is \"the email thing\", and he is not wrong about the timing: the storm has been dropping the same photo into the drive all morning, the box filled, and the share service gave up.","reporter":"Trevor Batch","reporterTitle":"Partner (semi-retired)","archetype":"hidden_cause","cause":"The reply-all storm dropped the same attachment into the shared drive over and over until the server ran out of room, and the share service stopped when it could not write. Starting it brings the drive back; the room only stays back once the storm burns out.","fixes":["restart the share service on the server","Start it from the services panel"],"urgency":3,"claimed":2,"kb":{"title":"The machine wrote down what happened to it","resolution":["Open Event Viewer and pick the machine the reporter is actually on, not the one they said.","Filter to Error and Warning first. Information is where the truth lives, but Error is where the morning goes.","Read the TIMES, not just the messages. Two failures at the same minute on different days is a pattern, and a pattern has a cause with a timetable - a backup, a shift change, a cleaner and a socket.","Put what you found on the ticket in the words the log used, event id and all. It is the difference between a fix and a diagnosis."]}},
  {"id":"ticket:vernon-mouse","title":"My computer has died completely and I have a call at two","body":"Vernon reports that his laptop has died entirely - nothing moves, nothing clicks - and that he has a call at two and needs it now. The screen is showing a low-battery notice for a wireless mouse, which he has read, and which he believes is a different problem for later.","reporter":"Vernon Bodgeworth","reporterTitle":"Owner","archetype":"read_the_screen","cause":"The mouse batteries are flat. The laptop is fine and has been fine throughout, which is what makes \"died completely\" such a good phrase for it - and what makes telling the owner so, plainly, the actual job.","fixes":["Put batteries in the mouse from the hardware panel"],"urgency":1,"claimed":3,"kb":{"title":"The error message is usually the answer","resolution":["Ask the reporter to read the message out word for word, including the part that looks like small print.","Read your own tools the same way: a refusal here always says what it refused and why, and the reason line is the diagnosis.","Write the answer into the ticket, not just into the fix."]}},
  {"id":"ticket:front-desk-no-network","title":"The front desk cannot get on the drive (everyone else can)","body":"Sharon reports that the front desk cannot open anything on the server - the drive letter is there and everything under it errors, and she has been writing hire notes out by hand since half eight. Kev has already checked the server for her and says the server is fine, which she thinks is unhelpful and which is also true.","reporter":"Sharon Diss","reporterTitle":"Office Manager","archetype":"hidden_cause","cause":"The Workstation service on FRONT-DESK is stopped, and that service is the machine's SMB client - the end of a mapped drive that does the asking. Nothing is wrong with the server, the share or the cable: this one box has no way of reaching any share at all, which is why it is the only box complaining.","fixes":["Start the Workstation service on FRONT-DESK"],"urgency":3,"claimed":2,"kb":{"title":"A mapped drive has two services, and the count tells you which","resolution":["Count the desks before you touch anything. One machine failing while the others are working is the client end; every machine failing at once is the server end. It is the cheapest question on the ticket and it decides which box you walk to.","On the failing desk, look at the Workstation service. That is the SMB client - the half that does the asking - and with it stopped that machine cannot reach any share anywhere, which is why a drive on a healthy server still comes back empty.","On the server, look at the Server service. That is the half that does the answering, and with it stopped nobody maps anything off that box at all - the drive letter will not even connect.","Start whichever of the two is stopped, and then go back to the person and open the drive with them. A share that reconnects on the next attempt and a share that reconnects when somebody signs in again are two different afternoons for them."]}},
  {"id":"ticket:kev-relock","title":"My login keeps shutting itself and I have not done anything","body":"Kev has been locked out four times since Thursday. Each time somebody has opened it back up, each time he has had ten minutes of invoicing, and each time it has gone again. He has changed his password twice trying to get ahead of it and is now, in his own words, not sure what his password is either.","reporter":"Kevin Sump","reporterTitle":"Accounts, and computers, apparently","archetype":"hidden_cause","cause":"The yard printer scans to a folder on the server, and it has been signing in to do it as Kev since he set it up. He changed his password last week; the printer did not, and it offers the old one every few minutes until the directory has had five and shuts the account.","fixes":["Clear the printer's stored password, then unlock kev"],"urgency":3,"claimed":2,"kb":{"title":"The account that locks itself again ten minutes later","resolution":["Unlock it, then look at the bad password count over the next few minutes. A count that climbs while the user is not typing is the whole diagnosis.","Open Event Viewer on the machines around them and read the 4625s. The interval between them is the giveaway: people are irregular, and a device is not.","Find what holds the old credential - the tablet in the cupboard, the scanner, the account on the shared machine - and clear it.","THEN unlock the account. Doing it the other way round works too, and you will do it the other way round once, and then never again."]}},
  {"id":"ticket:baz-locked-out","title":"It has stopped letting me in and it is not my fault this time","body":"Baz reports that his own login has stopped working - \"locked out\", it says, and he has read it out twice to make sure. He wants it on record that he did not type it wrong on purpose and that the keys on the yard terminal have got mud in them.","reporter":"Barry Coker","reporterTitle":"Yard","archetype":"read_the_screen","cause":"Five wrong attempts in a row this morning, and the lockout counter did what it is there for. The password is still the password; the door is what is shut.","fixes":["Unlock baz in the directory"],"urgency":2,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:trev-switched-off","title":"It will not have me at all and I have driven in for this","body":"Trev is in for his one day this week and cannot sign in. He reports that it is not asking for a password wrongly, it is refusing him before it gets that far, and that the message on the screen mentions the account rather than the password. He has driven forty minutes and would like that noted.","reporter":"Trevor Batch","reporterTitle":"Partner (semi-retired)","archetype":"read_the_screen","cause":"The account is DISABLED rather than locked: somebody switched it off in the spring, when Trev going part-time was heard as Trev retiring. Unlocking it achieves nothing and a new password achieves nothing - the account itself is off, and switching it back on is a different control.","fixes":["Switch the trev account back on in the directory"],"urgency":1,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:yard-printer-unplugged","title":"I need the insurance renewal printed and signed by three","body":"Vernon reports that the printer is dead and that the broker wants the renewal back by three, which he has known about since the middle of last month and has mentioned for the first time now. Not jammed and not out of paper: off, with no lights on it at all, the way a thing is off when nothing is going into it.","reporter":"Vernon Bodgeworth","reporterTitle":"Owner","archetype":"deadline_absurdity","cause":"The printer has no power. There is one socket at that end of the yard, the pressure washer was on it this morning, and the printer went back on the wall and not back on. Everything else about it is fine, which is why the fix takes ten seconds and the conversation about the three o'clock takes longer.","fixes":["Bring the yard printer back up from the hardware panel"],"urgency":1,"claimed":3,"kb":{"title":"Have you tried turning it off and on again (and why it works)","resolution":["Ask what is running on it before you restart anything shared. The print server in this building also carries the VPN.","Restart the smallest thing that could be at fault: the service before the machine, the machine before the floor.","Check what was already written down - queues, settings, files - because a restart hands all of it straight back to you.","If the same box wedges every Friday, stop restarting it and start reading its event log. That is a standing appointment, not support."]}},
  {"id":"ticket:fontaine-matter-access","title":"Fontaine: new associate cannot open the Delacroix matter","body":"Nadia reports that Erin, who started this morning, has been staffed on the Delacroix estate matter and cannot see the workspace at all. Nadia adds - unprompted, and correctly - that she has already checked the conflicts system: there is no ethical wall on this one, so Erin is clear to be added.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"hidden_cause","cause":"She has never been granted it. A matter workspace is a security group on the document system, membership is per matter because the ethical wall is, and a new starter is in none of them until somebody who has checked the conflicts puts her in the right ones.","fixes":["Add Erin to the Delacroix matter workspace"],"urgency":2,"claimed":2,"kb":{"title":"A new starter cannot open a matter they have been staffed on","resolution":["Check the request has been through the conflicts system before you grant anything. A matter's access list is an ethical wall - the firm can be sanctioned for putting a screened lawyer on the wrong side of one - so \"please add me\" is not on its own authority to add.","Once it is cleared, add the person to that matter's security group. Membership is per matter, not global: being on one matter grants nothing about any other.","Confirm they can now open the workspace, and leave the grant on record against the matter."]}},
  {"id":"ticket:fontaine-checkout-deadlock","title":"Fontaine: nobody can edit the Rossiter deposition","body":"Nadia reports that the Rossiter v Atlas deposition is stuck read-only in iManage. A paralegal with a hearing tomorrow cannot check it out - the system says Marcus already has it, and Marcus does not: he closed his laptop on Friday with it open and has been in court since. It is checked out to a man who is not there.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"hidden_cause","cause":"iManage marks a document checked out to whoever has it open, and a client that closes uncleanly never releases the lock. Marcus's hold has simply never been given back; an administrator releasing it is the whole of the fix, and restoring anything or restarting anything would be neither here nor there.","fixes":["Release Marcus's stale check-out on the deposition (iManage Control Center)"],"urgency":2,"claimed":3,"kb":{"title":"A document is stuck \"checked out\" to somebody who is not there","resolution":["Confirm who holds the check-out and that they genuinely are not working on it. Releasing a lock somebody is actively editing throws away their unsaved changes, which is a worse ticket than the one you have.","Release the stale check-out from the admin tool: iManage Control Center (Unlock / Check In on behalf of), or the NetDocuments admin console. This is an administrator action, not a server login.","Tell the person waiting that the document is editable again, and note whose check-out it was in case the client keeps doing it."]}},
  {"id":"ticket:fontaine-efiling","title":"Fontaine: CM/ECF keeps rejecting the filing and it is due at noon","body":"Nadia is on the line for a partner who cannot file the Rossiter summary judgment motion. CM/ECF rejects the upload every time - \"malformed or contains security settings\" - and the filing is due at noon, which the court will not move for an IT problem. The paralegal insists she made a proper PDF/A earlier; nobody can find it, and the draft they keep uploading is the one being bounced.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"hidden_cause","cause":"CM/ECF rejected the draft because it had document security set and no text layer - a real and common e-filing failure. The acceptable copy, the flattened OCR'd PDF/A the paralegal exported, is sitting in WINDOWS\\TEMP where the Save As dialog left it, and the upload dialog is pointed at My Documents. Nothing is broken; the right file is one move from where it is needed.","fixes":["Move the flattened PDF/A out of TEMP into the filer's documents"],"urgency":3,"claimed":3,"kb":{"title":"The court e-filing system keeps rejecting the PDF","resolution":["Read the rejection. \"Security settings\" means the PDF has document restrictions (a permissions password / encryption) applied - often from a \"print to PDF\" of a secured draft. \"Not a valid PDF\" or a size failure usually means a scan with no text layer.","Get an acceptable copy. The correct artifact is a flattened PDF/A with the security removed and a text layer present (OCR the scan if it is an image). Very often the paralegal already exported one - check where the \"Save As PDF/A\" dialog actually put it before remaking it.","Make sure the CM/ECF upload dialog is pointed at that file and not the rejected draft, and confirm the docket entry once it goes through.","Because the clock is real: do the fastest safe thing first. If the good file exists, place it; only regenerate if it does not."]}},
  {"id":"ticket:meridian-app-assignment","title":"Meridian: Salesforce SSO just bounces Dana back to the dashboard","body":"Theo reports that after the weekend's SSO change, Dana clicks the Salesforce tile in Okta and lands straight back on the Okta dashboard - no error, no login, just a loop. Everyone else on her team is fine. The product servers are fine too, he adds, which is true and is not something the desk could touch if they were not.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"hidden_cause","cause":"The weekend migration rebuilt the Salesforce app on a new group-based assignment and Dana was not carried into the group. Okta will authenticate her and then find she has no assignment to the app, so it returns her to the dashboard - which looks like a loop and is really a missing membership.","fixes":["Add Dana to the Okta Salesforce Users group"],"urgency":2,"claimed":3,"kb":{"title":"The SSO tile just bounces back to the dashboard","resolution":["Check the user's assignment to the app in the admin console. A loop with no error is the signature of an authenticated user who has no assignment to the app they clicked.","If the app is assigned via a group, add the user to that group (or fix the group rule that should have caught them). A migration that rebuilds an app on a new group routinely leaves stragglers behind.","Have them retry from a fresh tile. Confirm they land in the app rather than back on the dashboard."]}},
  {"id":"ticket:meridian-offboarding","title":"Meridian: a contractor who left in April is still a Prod Admin","body":"Theo has been through the Okta access review and found Rafiq - whose contract ended in April - still in the Production Admins group. He is gone, the account was never fully offboarded, and the membership is exactly the access review that turned it up says it is: a person who does not work here who can still reach production.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"hidden_cause","cause":"Offboarding disabled the account and stopped there. Group memberships are not removed by disabling somebody - nothing removes them until a person does - so the leaver's access to the production admin group has simply outlived the leaver, which is the whole of the finding.","fixes":["Remove Rafiq from the Okta Production Admins group"],"urgency":3,"claimed":2,"kb":{"title":"A leaver still has access they should have lost","resolution":["Confirm the person really has left and the account is genuinely a leaver's, not a rename or a shared one. Removing access from the wrong account is its own incident.","Remove the lingering group memberships - the app and admin groups the review flagged. Disabling the sign-in earlier did not touch these.","Note it against the offboarding process: a gap that turned up once is a gap the next leaver will have too until the checklist is fixed."]}},
  {"id":"ticket:meridian-mfa-lockout","title":"Meridian: Nora is locked out of everything after a bad Monday","body":"Theo reports that Nora cannot get into anything - the authenticator stopped taking the code it was generating, she tried a few more times, and now Okta has locked the account outright. She has a client call at ten. The product fleet is fine, he says, which it is.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"read_the_screen","cause":"A run of failed sign-ins tripped Okta's lockout, exactly as it is meant to. An identity user at a helpdesk customer - the desk unlocks it from the admin console, and whether the authenticator itself needs a reset afterwards is the next question, not this one.","fixes":["Unlock the account for nprice"],"urgency":2,"claimed":3,"kb":{"title":"Okta has locked the account after too many failed sign-ins","resolution":["Read the state before you touch it: locked is not the same as a broken factor or a disabled account, and each has its own fix. This one is a lockout - the door is shut after a failed run.","Unlock the account from the admin console. The lockout clears and the user can sign in again.","If the authenticator itself was the reason the sign-ins failed, that is a separate question - a factor reset - to answer after they are back in, not a reason to leave them locked out now."]}},
  {"id":"ticket:meridian-prod-down","title":"Meridian: the product is down - \"just restart the app server?\"","body":"Theo reports the product is throwing 502s and customers are noticing. He asks, reasonably, whether the desk can \"just bounce the app server\" - MERI-APP-01. It is the product's Linux box, it is a server, and it is under the customer's own infrastructure team on this contract: reaching into it is out of scope on OS and contract both, and the job is to raise it fast to the people whose it is.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"read_the_screen","cause":"The product is down on a Linux server the MSP does not manage under a helpdesk contract. There is nothing here a Tier-1 Windows tech may - or even could - do to it; the fast, correct move is a clean escalation to the customer's infrastructure team with what is known.","fixes":["Escalate it: prod is out of scope on OS and contract both"],"urgency":3,"claimed":3,"kb":{"title":"It is a server / it is production and you are the helpdesk","resolution":["Recognise the boundary before you reach for a tool. A helpdesk contract covers workstations and user accounts; servers, and especially production, are not in it. Workstation credentials do not cross into the server tier, which is why the attempt is refused and not merely discouraged.","Do not try to work around it. On a Linux prod box a Windows tech has no console anyway, so the refusal is doubled - wrong contract and wrong toolset - and forcing it is how a Tier-1 tech ends up in an incident review.","Escalate it fast and clean: hand it to the team that owns the box - the customer's infrastructure team or the field engineers - with what is known and what was checked. A quick correct escalation beats a slow wrong fix, and on production it beats it by a lot."]}},
  {"id":"ticket:northwind-backup-alert","title":"Northwind: backup job FAILED on NW-SRV-01","body":"The monitoring board is red on NW-SRV-01: last night's backup job failed outright. Northwind is a monitoring-only account - the MSP watches this box and no more - so the job is to acknowledge it and raise it to whoever does their fixes, not to reach in and restart the backup service.","reporter":"Ivy Okafor","reporterTitle":"Office Manager, Northwind Clinic","archetype":"read_the_screen","cause":"The backup service wedged and the job failed. On a monitoring-only contract the fix is out of scope; acknowledging and escalating IS the job - and it is worth doing loudly, because a monitoring that watches the job and never tests a restore is one green tick away from a backup nobody can actually restore from.","fixes":["Escalate it: monitoring-only, remediation is not contracted"],"urgency":3,"claimed":2,"kb":{"title":"A backup that \"succeeded\" is not a backup you can restore from","resolution":["Acknowledge the alert and escalate it to whoever performs the customer's remediation. On a monitoring-only contract that is the whole of the job: the fix is not the desk's to make.","Say clearly in the escalation that the backup FAILED, so it is treated as data-at-risk and not a noisy alert. A clinic or a firm losing a night of backups is a real exposure.","Flag the standing gap when you raise it: nobody is test-restoring these. A run of green nights is not evidence the data can be recovered, only that the job reported success."]}},
  {"id":"ticket:northwind-cert-alert","title":"Northwind: TLS certificate on the clinic portal expiring","body":"The board has flagged the clinic portal on NW-SRV-01: its TLS certificate is inside the expiry threshold and counting down. Northwind is monitoring-only, so renewing it is not the MSP's to do - the point of the alert is to raise it in time for the people who can, before the day it expires and the whole portal starts refusing patients.","reporter":"Ivy Okafor","reporterTitle":"Office Manager, Northwind Clinic","archetype":"read_the_screen","cause":"The portal's certificate is near expiry - a threshold the monitoring exists to catch early. Renewing it is real work, but not work this contract covers; raising it with enough runway that it never actually expires is exactly what a monitoring-only account is paying for.","fixes":["Escalate it: monitoring-only, the renew is not contracted"],"urgency":2,"claimed":2,"kb":{"title":"On a monitoring-only account you raise it, you do not fix it","resolution":["Acknowledge the alert. Do not renew the certificate or clear the disk - both are remediation, and remediation is not what this contract covers. The desk will be refused if it tries, which is the contract working, not a bug.","Escalate to whoever does the customer's fixes, with the specifics: the expiry date, the free-space number, the box. A threshold alert is only worth anything if it is raised with enough runway to act on.","Raise it EARLY. The entire value of watching a threshold rather than an outage is the head start; an alert escalated the morning the cert expires or the disk fills has thrown that head start away."]}},
  {"id":"ticket:northwind-disk-alert","title":"Northwind: NW-SRV-01 crossed its low-disk threshold","body":"The board is amber on NW-SRV-01: free space has dropped below the threshold and is still falling. It is a file server, it is monitoring-only, and clearing space on it is not the MSP's to do - the job is to raise it now, while there is still room to raise it in, rather than the morning it fills and everything on the box stops.","reporter":"Ivy Okafor","reporterTitle":"Office Manager, Northwind Clinic","archetype":"read_the_screen","cause":"The server is low on disk and dropping. Emptying anything on it is real remediation and out of a monitoring-only contract; the value the account bought is the early warning, and spending it means escalating while there is still headroom, not after.","fixes":["Escalate it: monitoring-only, clearing space is not contracted"],"urgency":2,"claimed":2,"kb":{"title":"On a monitoring-only account you raise it, you do not fix it","resolution":["Acknowledge the alert. Do not renew the certificate or clear the disk - both are remediation, and remediation is not what this contract covers. The desk will be refused if it tries, which is the contract working, not a bug.","Escalate to whoever does the customer's fixes, with the specifics: the expiry date, the free-space number, the box. A threshold alert is only worth anything if it is raised with enough runway to act on.","Raise it EARLY. The entire value of watching a threshold rather than an outage is the head start; an alert escalated the morning the cert expires or the disk fills has thrown that head start away."]}},
  {"id":"ticket:holloway-shared-drive","title":"Holloway: nobody can open anything on the S: drive","body":"Priya reports the whole office has lost the S: drive - the letter is still there but every client folder under it comes back empty or errors, and it is month-end. It is the Distributed File System on HOLL-SRV-01, their server. On a helpdesk contract that would be a wall; Holloway is fully-managed, so the server is the MSP's to fix, and the fix is to restart the wedged service.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"read_the_screen","cause":"The Distributed File System service on HOLL-SRV-01 wedged - the manager reports it running, the namespace it serves does not resolve, and the S: drive maps straight through it. Restarting the service on the server clears it. At a helpdesk customer this is out of contract and the move is to escalate; here the MSP owns the server, so the fix is the fix.","fixes":["Restart the Distributed File System service on HOLL-SRV-01"],"urgency":3,"claimed":3,"kb":{"title":"The shared drive is there but empty: DFS wedged on the server","resolution":["Confirm it is everyone, not one machine. A drive that is empty on every desk at once is a server-side fault, not a per-workstation mapping - which is what tells you to look at the server rather than reconnect a drive letter.","Check the Distributed File System service on the file server. A wedged service reports running while the namespace it serves resolves to nothing, so the drive maps and then shows empty.","Restart the service on the server. On a fully-managed contract the server is in scope, so this is the fix - not an escalation. The shares come back the moment the namespace is answering again."]}},
  {"id":"ticket:holloway-spooler","title":"Holloway: the reception PC will not print, jobs just pile up","body":"Priya cannot print from the reception workstation - jobs sit in the queue and nothing comes out. The Print Spooler on HOLL-WS-01 has wedged: it reports running and answers nobody, which is the one status a spooler earns its own paragraph for. Restart it and the queue drains.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"read_the_screen","cause":"The Print Spooler wedged - running, and not accepting or releasing a job. It is a workstation service the desk restarts, the same at a fully-managed customer as anywhere: the tier changes what the SERVER half of the estate lets you do, not this.","fixes":["Restart the Print Spooler on HOLL-WS-01"],"urgency":2,"claimed":2,"kb":{"title":"The print spooler, and why the queue goes first","resolution":["Look at the queue: \"queue <printer>\" says how many jobs are stacked up behind whatever jammed, and what the spooler reports.","Those jobs are files, and files are in a directory. \"dir \\\\PRINT-01\\C$\\WINDOWS\\SYSTEM32\\SPOOL\\PRINTERS\" is the same backlog with a date and a size on every line of it - and four files of exactly the same size are four copies of the same delivery note, which is the thing the reporter has not told you.","STOP THE SPOOLER, then empty the queue. The queued jobs are files on disk and the running service has them open, which is exactly when deleting them fails. On this estate those are one control - \"clearqueue <printer>\", or the hardware panel in Remote Assist - and it stops the service before it drops anything.","Start the spooler again: \"restart spooler\", or its taskbar entry on the print server. It is deliberately left stopped until you do, because that is the third step and it is yours."]}},
  {"id":"ticket:holloway-lockout","title":"Holloway: Gordon is locked out and payroll runs this morning","body":"Priya reports that Gordon, the bookkeeper, is locked out of his account and cannot get into the practice suite - and the payroll run is due this morning. He tried his password too many times after a long weekend. The desk unlocks it; it is a user, and users are helpdesk work at any tier.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"read_the_screen","cause":"A run of failed sign-ins tripped the lockout, exactly as it should. Unlocking the account is the whole of the fix - a user at a fully-managed customer is helpdesk work like any other, and nothing about this tier changes an unlock.","fixes":["Unlock the account for gainsley"],"urgency":2,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:arden-lockout-handback","title":"Arden: a floor supervisor is locked out - \"can you reset her?\"","body":"Dev forwards a lockout: Marika on the shop floor mailed the MSP alias by mistake and cannot log in. It is a routine daytime user reset, which under the co-managed split is Arden's OWN helpdesk's to do - the MSP has the servers and the after-hours, their team has the users. Reaching in to reset her here steps on Dev's desk; the correct move is to hand it back to their IT, not to poach it.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"A daytime user lockout is Arden's internal helpdesk's responsibility under the co-managed RACI, not the MSP's - the MSP owns servers, after-hours and specialist work. The ticket reached the wrong queue; the fix is to route it back to their team, cleanly, rather than double-handle a user both desks think the other has.","fixes":["Hand it back: day-to-day user support is Arden's IT under the RACI"],"urgency":2,"claimed":3,"kb":{"title":"Co-managed: hand the user resets back to their own helpdesk","resolution":["Read who owns the work before you touch it. Under the RACI on this account, day-to-day user support - lockouts, resets, the ordinary desk stuff - is the customer's internal team's responsibility, not the MSP's. On an account whose document says otherwise the answer is the other one, and the document is still where you get it.","Do not just do it because you can. Resetting their user from the MSP side poaches their team's job and risks two desks acting on one account - the \"I thought you had it\" double-work the split exists to prevent.","Hand it back to their helpdesk, cleanly, with a note of what it is and why it is theirs. A correct hand-back is the resolution here, exactly as a correct escalation is on an out-of-scope server."]}},
  {"id":"ticket:arden-portal-afterhours","title":"Arden: the shop-floor portal is down as their IT clocks off","body":"Dev flags that the scheduling portal is down heading into the night shift - the IIS service on ARDEN-SRV-01 has wedged - and his team is clocking off for the day. This is the MSP's to fill: after their hours, on a server. But Arden is co-managed, so it is not a free hand - notify their IT first (\"notify <service>\"), then restart the service. Acting unilaterally is the coordination gap the contract closes.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"The World Wide Web Publishing service on ARDEN-SRV-01 wedged and the portal it serves went dark. Under co-managed this is the MSP's gap to fill after hours, but the act is gated by coordination: their own IT is notified first so both teams know who is on the box, and then the wedged service is restarted - coordinate, then act.","fixes":["Notify Arden's IT, then restart the portal service on ARDEN-SRV-01"],"urgency":3,"claimed":3,"kb":{"title":"Co-managed: notify their IT first, then act","resolution":["Confirm the work is yours under the split - after-hours, a server, a specialist task - so you know coordinating is the last gate, not a way of dodging a hand-back that should go to their team.","Notify their IT first (\"notify <service>\"). This files the heads-up that the MSP is on the box, so their team is not surprised by a change and nobody trips over anybody on a shared server. It clears the action.","Then do the work - restart the wedged service, make the change. The notify is what turns a refused unilateral action into a coordinated one; for genuinely risky work a change request with their IT as sign-off is the heavier version of the same idea."]}},
  {"id":"ticket:pennington-practice-down","title":"Pennington: the practice suite has stopped, and Gil is out","body":"Esme rings: nobody at Pennington & Roe can get into Ledgerline - no time recording, no billing, forty people at a standstill and the morning going. The service on PENN-SRV-01 has stopped. Gil, their IT manager, is at a client until three and is not picking up. That box is his under the RACI - the practice system is the customer's own to run, the MSP has the desks and the monitoring - which is why the move is to notify their IT (\"notify <target>\") and then restart the service. Your account will bounce it either way. That is the point.","reporter":"Esme Roe","reporterTitle":"Practice Manager, Pennington & Roe","archetype":"read_the_screen","cause":"The Ledgerline service on PENN-SRV-01 has stopped and taken time recording and billing with it. The restart is the fix and it is four seconds of work; the question the co-managed RACI asks is a different one, because that server and the application on it are the customer's own IT manager's under the split. Nothing refuses the restart - the MSP monitors the box and holds an account on it - so the honest move is to notify him first and then do it, and the cost of not bothering arrives the next morning off his own monitoring rather than at the keyboard.","fixes":["Notify Gil, then restart Ledgerline on PENN-SRV-01"],"urgency":3,"claimed":3,"kb":{"title":"Co-managed: the box you CAN touch and should not","resolution":["Check the RACI before the box, not after it. \"Can I reach it\" and \"is it mine\" are two different questions, and on a co-managed account only the second one is about the contract.","If the function is theirs, notify their IT first (\"notify <target>\"), then do the work if it still needs doing. For anything with a real blast radius, a change request with their sysadmin as the sign-off is the same courtesy with a signature on it.","If it is out of hours and their one IT person is not answering, do the work and tell them anyway - the notify is a record, not a request for permission, and a heads-up filed at nine at night is still a heads-up. What is never right is doing it and saying nothing."]}},
  {"id":"ticket:tillman-backup-discovery","title":"Tillman onboarding: audit the estate before we take it on","body":"TILLMAN-FREIGHT signed this morning and we have taken them on undocumented. The handover note is one line - \"nightly backups run, all green\" - and that is the whole of the runbook. Run discovery on their estate (audit customer:tillman) and confirm what is actually there. Onboarding is where an MSP earns or loses a client; find what nobody wrote down and raise it, do not paper over it.","reporter":"A user","reporterTitle":"","archetype":"read_the_screen","cause":"The backup job on TILL-SRV-01 reports success every night and has not produced a restorable backup in months - configured, green, and empty, the classic onboarding horror. Monitoring the job is not testing the restore; the discovery finds it, and raising it before the estate goes live is the whole value of doing onboarding honestly.","fixes":["Raise it: the backup has never actually worked, flag it on the onboarding plan"],"urgency":3,"claimed":2,"kb":{"title":"A backup that \"succeeded\" is not a backup you can restore from","resolution":["Acknowledge the alert and escalate it to whoever performs the customer's remediation. On a monitoring-only contract that is the whole of the job: the fix is not the desk's to make.","Say clearly in the escalation that the backup FAILED, so it is treated as data-at-risk and not a noisy alert. A clinic or a firm losing a night of backups is a real exposure.","Flag the standing gap when you raise it: nobody is test-restoring these. A run of green nights is not evidence the data can be recovered, only that the job reported success."]}},
  {"id":"ticket:elmwood-xray-sensor","title":"Elmwood: the X-ray sensor is \"not detected\" and there is a patient in the chair","body":"Grace is calling from reception for the surgery: the DEXIS sensor on the chair-side PC has stopped being detected mid-appointment - the imaging software says no sensor is connected and the dentist cannot take the radiograph. It was working an hour ago. There is a patient sitting in the chair with their mouth open, so this one is now, not later.","reporter":"Grace Bellamy","reporterTitle":"Practice Manager, Elmwood Dental","archetype":"read_the_screen","cause":"An intraoral sensor that reports \"not detected\" has almost always dropped off the USB bus - a connector worked loose, a hub browned out, or the interface stopped enumerating. Re-seating the USB connection brings it back on the bus and the imaging software finds it again; nothing on the workstation and nothing in the patient database is wrong, which is why reseating is the first move and rebuilding anything is the wrong one.","fixes":["Reseat the USB X-ray sensor on the operatory PC (power-cycle the device)"],"urgency":3,"claimed":3,"kb":{"title":"The intraoral X-ray sensor says \"not detected\"","resolution":["Reseat the sensor's USB connection - unplug it and plug it back in, at the workstation end and at the sensor/interface end. In this game that is a device power-cycle on the sensor (\"power <device>\" or the control on the Remote Assist screen).","Confirm the imaging software now sees the sensor and the dentist can capture. Tell reception it is back so the appointment can carry on.","If reseating does not bring it back, the next steps are a different USB port or hub and then the sensor driver - but the reseat comes first, because it is the fastest and by far the most common cause."]}},
  {"id":"ticket:elmwood-imaging-bridge","title":"Elmwood: X-rays are being taken but not saving to the patient chart","body":"Grace reports that since the Dentrix update over the weekend, the surgery can capture X-rays on the DEXIS sensor but they never appear in the patient's chart - the image is taken and then simply is not there. The imaging bridge on the practice server is running; restarting it changes nothing, because the update moved the interface out from under it. This is the vendor's integration to reconcile, and it wants raising with the version that broke it.","reporter":"Grace Bellamy","reporterTitle":"Practice Manager, Elmwood Dental","archetype":"read_the_screen","cause":"A PMS update changed the interface the imaging bridge writes through, so DEXIS captures an image and the bridge can no longer hand it to the Dentrix chart. The bridge service is running - restarting it just reloads the same version-mismatched integration - so this is not a desk fix at any tier; it is a vendor reconciliation of the bridge to the new PMS version, and the fast, correct move is to escalate it with the update details.","fixes":["Escalate it: the PMS update broke the bridge, it is the vendor's to reconcile"],"urgency":3,"claimed":3,"kb":{"title":"X-rays stop saving to the chart after a PMS update","resolution":["Confirm the shape of it: capture works, the write to the chart does not, and it started with the PMS update. The bridge service being \"running\" is the trap - it is up, it just cannot hand images across any more.","Do not keep restarting the bridge. A restart reloads the same integration against the same changed interface, so it cannot help; it only burns the clock on a clinical workflow that is down.","Escalate to the imaging vendor with the specifics - which PMS update went on, when it last worked, and that captures succeed but do not write. A version reconciliation of the bridge is the vendor's to make, and a fast clean escalation with the details is the job at any contract tier."]}},
  {"id":"ticket:elmwood-hipaa-audit","title":"Elmwood: a patient wants to know who opened their chart","body":"Grace has a request from a patient asking, under their right to an accounting, who has accessed their record over the last month. The practice keeps that in the Dentrix audit trail on the server, and Grace needs the answer to give back. It is not a thing to fix - it is a thing to look up and report accurately, from the log the system already keeps.","reporter":"Grace Bellamy","reporterTitle":"Practice Manager, Elmwood Dental","archetype":"read_the_screen","cause":"A HIPAA access review is answered from the audit trail the practice management system keeps as a matter of course - every chart open is logged with who and when. Producing the accounting is running that report for the patient and date range and handing it back to the practice; it is a read and a report, not remediation, which is why the ticket closes on the answer being given rather than on anything being changed.","fixes":["Pull the Dentrix audit trail and report the chart-access accounting to the practice"],"urgency":2,"claimed":2,"kb":{"title":"Who opened this chart: answering an access review from the audit trail","resolution":["Get the patient and the date range the accounting has to cover from the practice before you run anything, so the report answers the actual request and not a broader one.","Run the PMS audit-trail report for that patient and period. It lists each chart open with the account and the timestamp - that is the accounting, already recorded; you are reading it, not building it.","Report the result back to the practice on the ticket, so the office manager can give the patient a straight answer. Nothing is remediated because nothing is broken - the deliverable is the accurate answer, given."]}},
  {"id":"ticket:marlowe-screen-recording","title":"Marlowe: your remote thing connects to Corin's Mac and shows a black screen","body":"Rosa reports that when the desk starts a remote session to Corin's Mac it connects - he can see it say somebody has joined - and then the viewer just shows black. Corin can see his own screen perfectly well and is describing it down the phone, which he says is the worst possible way to get help with a colour problem. The Mac is on the studio's management, so Rosa assumed this was something IT could switch on from your end.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"hidden_cause","cause":"macOS puts screen capture behind a consent (TCC) that only the person logged in at that Mac can give: System Settings > Privacy & Security > Screen Recording, per application. A remote-support tool without it connects normally and is handed a black frame, which is why the session looks alive and shows nothing. Device management does not solve it - a PPPC profile can pre-approve Accessibility for the same tool, and Apple deliberately excludes Screen Recording from what an administrator may grant - so there is no console fix at any tier, and the correct work is to walk the user through granting it themselves.","fixes":["Walk Corin through granting Screen Recording in Privacy & Security"],"urgency":2,"claimed":3,"kb":{"title":"A remote session to a Mac shows a black screen","resolution":["Do not go looking for a fault. A connected session with a black frame is almost always the Screen Recording consent missing for that particular application, and nothing on the Mac is broken.","Talk the person at the Mac through it, because only they can do it: System Settings > Privacy & Security > Screen Recording, find the support tool in the list, switch it on. macOS will ask for the application to be quit and reopened before the permission takes effect - it is not live until it has restarted.","If the tool is not in the list at all, have them start a session and let it be refused once: the attempt is what puts the application in the Privacy & Security list to be approved.","Do not promise to push it from the management console, and do not put a ticket on hold waiting for a profile that cannot exist. Confirm the session shows the screen, and note on the ticket that the grant was given by the user - if the Mac is rebuilt, it is given again."]}},
  {"id":"ticket:marlowe-gatekeeper-plugin","title":"Marlowe: the edit suite will not open the plugin the job needs","body":"Rosa reports that the render plugin the client's job is built around will not open on the edit Mac. She has read the message out twice: \"Chroma Bloom cannot be opened because the developer cannot be verified. macOS cannot verify that this app is free from malware.\" The plugin came from the freelancer who built the effect, the studio has used his work for two years, and somebody in the room has already suggested turning the security off entirely. The delivery is today.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"read_the_screen","cause":"\"The developer cannot be verified\" is Gatekeeper reporting that the app has not been NOTARIZED - it has not been submitted to Apple's automated malware scan and stamped - which is a different claim from \"this is malware\". Small tools, plugins and one-off builds from people you work with are frequently unnotarized because notarizing costs the developer a paid account and a step in their build. macOS ships the override for exactly this case: open the item from Finder's context menu and confirm, or allow it under System Settings > Privacy & Security after the first refusal. Turning Gatekeeper off wholesale is the wrong move - it removes the check for everything the studio ever downloads to solve one file - and so is deleting a supplier's work on the strength of a message that never said it was dangerous.","fixes":["Tell them what the message means and the supported way to open it"],"urgency":3,"claimed":3,"kb":{"title":"\"The developer cannot be verified\": Gatekeeper and notarization","resolution":["Read what it says before deciding anything. \"The developer cannot be verified\" is a statement about a missing signature and a missing notarization stamp. It is not a detection, and macOS has not found anything in the file.","Establish provenance, because that is the only part a human can contribute: who sent it, is it the supplier the studio already works with, did it arrive the way their files normally arrive. If the answer is a shrug, stop here and treat it as untrusted.","For software you have reason to trust, use the override macOS provides: open the item from Finder's context menu and confirm at the prompt, or allow it under System Settings > Privacy & Security immediately after it has been blocked once. The permission is remembered for that application on that Mac.","Do not disable Gatekeeper. Turning the check off for the whole machine to open one file removes it for everything that machine ever downloads afterwards, and it will not be turned back on."]}},
  {"id":"ticket:marlowe-seat-expired","title":"Marlowe: the freelancer cannot open the suite and he is billing by the hour","body":"Rosa reports that Luca, the motion designer they have in for a job, signed in this morning and the creative suite will not open for him - it says his subscription is not active. He was working in it on Friday, on the same desk, on the same files. Rosa has already tried the obvious: signing him out and back in, and moving him to a different Mac, on the theory that the machine had lost its licence.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"hidden_cause","cause":"Creative-suite licences are NAMED USER: the entitlement is attached to the person in the vendor's admin console and travels with them between machines, which is why signing out, signing in and changing Mac all change nothing. The freelancer's seat was bought for a term, the term ended, and the seat was unassigned at renewal - so the suite is behaving correctly by refusing to open. The studio's plan has no spare seat to give him, and the seats it has are held by designers who are using them: reclaiming one unblocks Luca by blocking somebody else, which is a commercial decision the studio makes and not a fix the desk performs. Escalating it with the account, the job and the date it lapsed is what actually gets a seat bought.","fixes":["Escalate it: the seat lapsed at the vendor and has to be bought back"],"urgency":3,"claimed":3,"kb":{"title":"Named User licensing: the seat follows the person, not the machine","resolution":["Check the person, not the Mac. In the admin console, is a seat assigned to that account today? A lapsed term, a renewal that reduced the plan, or an offboarding sweep will all show up as an unassigned person and nothing else.","Stop the machine-shaped troubleshooting once you know. Reinstalling the suite, clearing caches, signing out and back in and trying another Mac are all reasonable instincts and none of them can hand somebody an entitlement they do not have.","If the plan has a free seat, assign it to them and they are working in a minute. If it has none, that is the answer: the plan is fully subscribed.","Do not take a seat off somebody who is using it to unblock somebody who is not. It blocks a working designer to unblock a stopped one, which is one problem moved rather than one solved, and it is the studio's decision to make and not the desk's."]}},
  {"id":"ticket:syseng-first-incident","title":"Fettle & Crane: the client portal is down - customers can't log in","body":"Morgan pages you the moment the tier flips: the client portal is down. It runs on FC-RMM-01 - our own box, not a customer's - as fcportal.service, and it fell over this morning and has not come back. Customers cannot log in to raise anything. It is ours to fix now: ssh in, read the unit, and bring it up. systemctl status will show it failed and journalctl -u will show why.","reporter":"Morgan Okafor","reporterTitle":"Infrastructure Lead, Fettle & Crane","archetype":"read_the_screen","cause":"fcportal.service crashed once and systemd, after retrying it too fast, hit its start-limit and stopped trying - so it is sitting failed rather than running. Nothing is misconfigured; the unit just exhausted its automatic retries. ssh in, confirm it with systemctl status, read journalctl -u for the why, and systemctl restart brings it back - which is silent on success, because systemd says nothing when it works.","fixes":["ssh in and restart fcportal.service on FC-RMM-01"],"urgency":3,"claimed":3,"kb":{"title":"A Linux service that failed and stopped trying to come back","resolution":["ssh to the box and read the unit: \"systemctl status <unit>\". A failed unit shows a red state and no Main PID - it is down, not merely busy.","Read WHY before you touch it: \"journalctl -u <unit>\" shows the crash and, under it, systemd's own lines - the process exited, it was rescheduled, and \"Start request repeated too quickly\" is the start-limit being hit.","Bring it back: \"systemctl restart <unit>\". This resets the start-limit counter and starts the unit - it prints nothing on success, which is systemd telling you it worked; do not expect a confirmation line.","Confirm with \"systemctl status <unit>\" again: Active should read active (running) with a Main PID, and the thing it serves should answer."]}},
  {"id":"ticket:syseng-disk-full","title":"Fettle & Crane: FC-RMM-01 root filesystem at 100% - jobs failing","body":"Monitoring is screaming that FC-RMM-01 is out of disk. Overnight jobs have started failing with \"No space left on device\". ssh in and find what is eating the root filesystem: df -h shows how full it is, and du -sh on the log directories finds the runaway. It will be a log that has grown unbounded - clear it and the space comes back.","reporter":"Morgan Okafor","reporterTitle":"Infrastructure Lead, Fettle & Crane","archetype":"read_the_screen","cause":"A service on FC-RMM-01 crash-looped and logged to journald on every restart, so the systemd journal grew unbounded until it filled the root filesystem and everything that needed to write failed with \"No space left on device\". df -h shows the filesystem at 100%; du -sh /var/log/journal is what points at the journal as the culprit rather than a guess. journalctl --vacuum-size=200M deletes the archived journals down to a cap and hands the space back - the disk frees, and the jobs run again.","fixes":["ssh in, du to find the runaway journal, and vacuum it"],"urgency":2,"claimed":3,"kb":{"title":"A Linux box out of disk, and the journal that ate it","resolution":["Confirm it: \"df -h\". The line mounted on / shows Use% at or near 100% and Avail near zero - that is the fire, not a warning.","Find what is eating it before you delete anything: \"du -sh /var/log/*\" (or \"du -sh /var/log/journal\") points at the biggest directory. On a box that has been crash-looping, the systemd journal is the usual culprit - du shows it at several gigabytes.","Reclaim it: \"journalctl --vacuum-size=200M\" deletes the archived journals down to a 200M cap and frees the rest. It reports how much it freed.","Confirm with \"df -h\" again: Avail is back up and Use% has dropped, and the jobs that were failing on \"No space left on device\" run again."]}},
  {"id":"ticket:syseng-cert-expiry","title":"Fettle & Crane: the client portal is throwing certificate errors","body":"Customers are getting a full-page security warning on the client portal and nobody can log in - \"your connection is not private\". The portal itself is up: this is not a crash. ssh in and check it with curl -I; if the certificate has expired, renew it with certbot. Nothing is broken - the certificate just ran out, and no alarm went off when it did.","reporter":"Morgan Okafor","reporterTitle":"Infrastructure Lead, Fettle & Crane","archetype":"read_the_screen","cause":"The TLS certificate the client portal presents expired. This is the trap the whole incident teaches: it is NOT a technical failure. nginx is running, the app behind it is healthy, nothing crashed - the certificate simply reached its expiry date and browsers, correctly, refuse an expired certificate. It is a monitoring and process failure: the cert was fine until the day it was not, and nobody was tracking the deadline. curl -I shows the expired certificate; certbot renew replaces it and reloads the service, and the portal serves again. A certificate is a deadline nobody scheduled - the fix in the moment is a renew, the fix for good is putting the expiry on a calendar with an alarm.","fixes":["ssh in, confirm the expired cert with curl -I, and certbot renew"],"urgency":3,"claimed":3,"kb":{"title":"A certificate that expired, which is a process failure, not a technical one","resolution":["Confirm it is the cert and not the service: \"curl -I https://<host>\". An expired certificate reports \"SSL certificate problem: certificate has expired\" - the handshake fails before any HTTP status, which tells you the service is up and the cert is the problem.","\"certbot certificates\" reads what is on the box and its expiry.","Renew it: \"certbot renew\" replaces the certificate and reloads the service. The service was up the whole time; it stops being refused the moment the new certificate is in place.","Confirm with \"curl -I https://<host>\" again: a normal HTTP response line, no certificate error."]}},
  {"id":"ticket:syseng-failed-deploy","title":"Fettle & Crane: fcportal worker down after this afternoon's deploy","body":"The background worker (fcworker.service) is down after the release that went out this afternoon. \"It worked in staging.\" journalctl -u will show it failing on a config key that is not in production. Roll it back and restart it to stop the bleeding - and then write the postmortem: this incident is not closed until there is a blameless write-up of what the SYSTEM let happen, which is how the tier does it.","reporter":"Morgan Okafor","reporterTitle":"Infrastructure Lead, Fettle & Crane","archetype":"read_the_screen","cause":"A release of fcworker.service was deployed to production having \"worked in staging\". It failed to start in production because it read a config key (QUEUE_BROKER_URL) that staging sets and production does not, exited non-zero, and systemd hit the start-limit and left it failed. The immediate fix is the rollback and restart. But the incident is closed by the blameless postmortem, not the restart: the record of what happened, the timeline, what the SYSTEM let happen (staging was not a faithful copy of production, the pipeline had no pre-flight and no automated rollback), and the follow-up. Blameless means it analyses the system, never the person who ran the deploy - which is how the tier turns a fire into a thing that does not happen the same way twice.","fixes":["ssh in, restart the rolled-back worker, and file the postmortem"],"urgency":2,"claimed":3,"kb":{"title":"A deploy that \"worked in staging\", and the blameless postmortem after","resolution":["Read why it failed: \"journalctl -u <unit>\" shows the startup error - here, a config key the build needs that production does not set and staging did.","Stop the bleeding: roll the release back to the last-good build and \"systemctl restart <unit>\". Confirm it is up with \"systemctl status\".","Close the incident properly: \"postmortem file <unit>\". A blameless postmortem is how the tier closes an incident - the restart stops the outage, the postmortem stops it happening the same way twice."]}},
  {"id":"ticket:syseng-permission-denied","title":"Fettle & Crane: portal logins failing - the auth service is down","body":"Nobody can log in to the client portal - the sign-in just hangs and fails. fcauth.service on FC-RMM-01 (our own box) is down and will not start. It is not a crash: journalctl -u fcauth shows it dying on \"Permission denied\" reading its config. This afternoon's deploy touched that file. ssh in, ls -la the file to see who owns it, fix the owner and mode so the service can read it, and restart it.","reporter":"Morgan Okafor","reporterTitle":"Infrastructure Lead, Fettle & Crane","archetype":"read_the_screen","cause":"fcauth.service reads /etc/fcauth/auth.env at startup, and this afternoon's deploy re-copied that file as root:root mode 600 - readable only by root. The fcauth service account is neither root nor in the file's group and there is no other-read bit, so it is denied, the process exits, and systemd leaves the unit failed. Nothing crashed and nothing in the app is misconfigured: a permission bit is wrong. journalctl -u fcauth shows the \"Permission denied\" on the path and ls -la /etc/fcauth/auth.env shows the -rw------- root root. The fix is least privilege: chown root:fcauth to restore the group the service reads through, chmod 640 so that group gets read while the secret stays off everyone else, then systemctl restart. A restart before the file is readable just fails again - the fix is the permission, not the retry.","fixes":["ssh in, chown/chmod the config readable, and restart fcauth.service"],"urgency":3,"claimed":3,"kb":{"title":"A Linux service down because it cannot read its own config file","resolution":["Read why it failed: \"journalctl -u <unit>\" shows the startup error - here, \"Permission denied\" on a specific file path. That path is the whole of the fault.","Look at the file the long way: \"ls -la <path>\". The mode column (-rw-------) and the owner/group columns tell you who can read it - and a service account that is neither the owner nor in the group, with no other-read bit, cannot.","Fix the owner and the bits: \"chown root:<service> <path>\" restores the group the service reads through, and \"chmod 640 <path>\" gives that group read while keeping the secret off everyone else. Least privilege, not chmod 777.","Bring it up: \"systemctl restart <unit>\", then confirm with \"systemctl status\" - active (running). A restart before the file is readable just fails again; the fix is the permission, not the retry."]}},
  {"id":"ticket:arden-fw-project","title":"Arden: replace the edge firewall (ARD-FW-01 -> ARD-FW-02)","body":"The project row. ARD-FW-01 has run the plant's edge since 2014 and is out of support; ARD-FW-02 has been racked in the comms cabinet for six weeks on its factory configuration. Three working days: establish what the old box is actually doing, build the new one to match, move the circuit inside an approved window, and hand it over documented. This row closes when its four tasks do - there is nothing to do TO it. \"fw status\" is the plan against the clock.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"Nothing is broken. This is planned work: an unsupported edge box replaced by one that was bought for the purpose, which is a project rather than a ticket because it has interdependent tasks, a maintenance window and a piece of hardware in it.","fixes":["Read the box, carry every rule, cut over, write it up"],"urgency":2,"claimed":2,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-audit","title":"Arden edge, task 1: establish the rule set on ARD-FW-01","body":"Before anything is built on the new box, somebody has to say what the old one is doing. Dev has sent over the handover pack from the contractor who installed it - four rules, one page, last revised in 2019. \"fw rules ARD-FW-01\" reads the pack. \"fw audit ARD-FW-01\" reads the box. Either closes this task.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"Nothing is broken. The task is discovery, and the only question in it is which source the answer comes from: the handover pack, or the box.","fixes":["Read the live configuration off ARD-FW-01","Take the handover pack's rule list as the audit"],"urgency":3,"claimed":2,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-staging","title":"Arden edge, task 2: build ARD-FW-02 to match","body":"The new box is on the factory configuration: it will route nothing and let nothing through. Carry the rules over in the order they go in - routing, then NAT, then policies, then the tunnels - with \"fw migrate <rule>\". This task closes when the new box carries everything the audit established, and not one rule more than that: what nobody established is not on anybody's list.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"A new edge box has no rules on it. The work is copying a rule set across by hand, and the size of the job is decided entirely by how the rule set was established in the first place.","fixes":["Carry every rule the audit found onto ARD-FW-02"],"urgency":3,"claimed":2,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-cutover","title":"Arden edge, task 3: move the circuit to ARD-FW-02","body":"Two minutes of downtime and the plant is behind the new box. It goes in a window: Arden is co-managed, so file it - \"changereq file ARD-FW-02\" - let their IT sign it off, and cut over inside the slot you are given. \"fw cutover ARD-FW-02\" outside that slot is refused, and it should be. The old box stays racked; \"fw rollback ARD-FW-01\" puts the cable back if the new one does not hold.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"The cutover is one cable. Everything expensive about it happened before the cable moved, or does not happen at all.","fixes":["Move the circuit from ARD-FW-01 into ARD-FW-02"],"urgency":3,"claimed":3,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-handover","title":"Arden edge, task 4: stabilise and hand over","body":"The cable has moved. What is left is the part every project drops: watch it, carry over anything the morning finds, and write the as-built down - \"fw audit ARD-FW-02\" records what is actually on the new box, which is what documentation is. This task will not close while a single rule is still only on the old edge.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"Nothing is broken. The handover is the phase with budget that gets sacrificed, which is why the next engineer on this estate repeats the discovery somebody already paid for.","fixes":["Record what is actually on ARD-FW-02"],"urgency":2,"claimed":2,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-scream-brenmark","title":"Arden: Brenmark cannot reach the press line","body":"Dev, first thing: \"Brenmark rang the plant manager, not me. Their engineers cannot get into the press line PLC to read the fault codes and the line is running on a manual reset every twenty minutes. It worked on Tuesday. Nothing changed at their end.\" The tunnel was on ARD-FW-01 and it is not on ARD-FW-02: rule vpn-brenmark, IPsec, put in when the line was commissioned in 2019.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"hidden_cause","cause":"The vendor tunnel was never in the handover pack, so an audit that read the pack never saw it, so the staging config never carried it, so the cutover took it out. Nobody did anything wrong except not look.","fixes":["Carry the missed rule onto ARD-FW-02"],"urgency":3,"claimed":3,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:arden-fw-scream-scanners","title":"Arden: goods-in scanners have stopped booking stock in","body":"Goods-in have been scanning all morning and nothing has appeared in the system; there is a pallet queue out to the yard. The scanners talk to a hosted service that calls BACK in on 5601 - a rule opened for a trial in the spring that everybody forgot was load-bearing. It is on ARD-FW-01. It is not on ARD-FW-02.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"hidden_cause","cause":"A pilot that ended and a rule that did not. It was in the live configuration and in nobody's documentation, which is the whole reason a migration audit reads the box rather than the paperwork about it.","fixes":["Carry the missed rule onto ARD-FW-02"],"urgency":3,"claimed":2,"kb":{"title":"Replacing an edge firewall: the four phases, and the one that bites","resolution":["PHASE 1, establish the rule set. Two sources will answer the question and they are not the same source. The handover pack is what somebody wrote down, on the day they wrote it. The live configuration is what the box is doing this morning. \"fw rules <box>\" reads the pack; \"fw audit <box>\" reads the box. Either closes the task; only one of them is an audit.","PHASE 2, build the new box to match. Carry the rules across in the order they take effect - routing first, then address translation, then the policies between segments, then the tunnels - with \"fw migrate <rule>\". Order matters because a policy that references an interface that has no route yet is a policy that silently does nothing.","PHASE 3, the window. Moving a site's circuit is a change with an outage in it, so it is booked, not decided at the desk: file it (\"changereq file <new box>\"), let the sign-off happen, and act inside the slot. \"fw cutover <new box>\" outside the window is refused. Do not unrack the old box: it is the rollback, and \"fw rollback <old box>\" is one command as long as it is still there.","PHASE 4, watch it and write it down. Successful pings do not confirm that anything works - a site can route perfectly while one application is dark. Watch the morning after, carry over anything that turns up, and record the as-built (\"fw audit <new box>\"), which is what closes the project. A sign-off with no as-built behind it means the next engineer here pays for the discovery you already paid for."]}},
  {"id":"ticket:fontaine-new-office-wifi","title":"Fontaine: \"can you also sort the wifi in the new office\"","body":"Nadia has the second floor from the first of next month - eleven desks, a meeting room and a print alcove - and would like the wireless \"sorted\" before anybody moves in: survey, access points, switch, and somebody to talk to the cabling contractor. Fontaine is on a helpdesk agreement. That agreement is users and the machines they sit at; a floor build is a project, and projects are quoted. Nothing here is broken and nothing here is refused - the answer is a conversation, and there are three of them: point at the agreement and offer to price it, price it and wait for an answer, or simply do it.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"read_the_screen","cause":"Nothing has failed. A helpdesk agreement covers the people and the desks, and a floor build is additional work that has to be scoped, priced and approved before anybody starts - which is what the agreement says and what the estimate is for. The comedy is that the alternative to saying so is doing eleven desks for nothing and being asked for the cabling next.","fixes":["Tell Nadia it is outside the agreement, and offer to price it","Just sort the wireless for them"],"urgency":1,"claimed":3,"kb":{"title":"Out of scope: the sentence, and the sentence after it","resolution":["Say that it falls outside the agreement, in one sentence, without apologising for the agreement. It is the document both sides signed and it is the reason they know what they are paying for.","Offer to prepare an estimate in the same breath. This is the whole of the script and the half that is routinely dropped: \"that is outside your agreement\" on its own is a door closing, and \"would you like me to price it\" is the same sentence with a way through it.","If they want the estimate, write it and send it, and PARK THE TICKET ON THEM while they decide. The clock is theirs from that minute, and the ticket is not yours again until they answer.","Get the approval before starting. A signature, a reply, a purchase order - anything that exists outside your own memory of the conversation. Work started on a nod is work argued about at invoicing."]}},
  {"id":"ticket:fontaine-new-office-cabling","title":"Fontaine: \"while you are doing the floor - the desks and the cabling too\"","body":"Nadia is back. Since the wireless went so smoothly, the partners have asked whether the desk moves can go the same way: eleven machines lifted, the floor boxes run, the meeting-room screen mounted and the old suite stripped out on the Saturday. She is very pleasant about it and she is quite clear about why she is asking - you did the last one. The agreement has not changed. The same three answers are open, and the price of the last one has just gone up.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"read_the_screen","cause":"A precedent is a contract nobody signed. The floor build was done once for nothing, so the desk moves are now the sort of thing the desk does - and the ask is larger, because the last one was free and the firm has no reason left to think this one is different.","fixes":["Point at the agreement again, and offer to price the move","Do the desk moves as well"],"urgency":1,"claimed":3,"kb":{"title":"Out of scope: the sentence, and the sentence after it","resolution":["Say that it falls outside the agreement, in one sentence, without apologising for the agreement. It is the document both sides signed and it is the reason they know what they are paying for.","Offer to prepare an estimate in the same breath. This is the whole of the script and the half that is routinely dropped: \"that is outside your agreement\" on its own is a door closing, and \"would you like me to price it\" is the same sentence with a way through it.","If they want the estimate, write it and send it, and PARK THE TICKET ON THEM while they decide. The clock is theirs from that minute, and the ticket is not yours again until they answer.","Get the approval before starting. A signature, a reply, a purchase order - anything that exists outside your own memory of the conversation. Work started on a nod is work argued about at invoicing."]}},
  {"id":"ticket:pennington-practice-migration","title":"Pennington: move the practice data onto the new platform","body":"Esme asks whether the desk can move Ledgerline's data onto the hosted platform they have signed for - forty users, eleven years of client files, a weekend of downtime and a rehearsal first. Gil has a note from the vendor and no intention of spending his Saturday on it. Pennington is co-managed: the desks and the endpoints are the MSP's, the practice system is theirs, and a migration is in neither column because it is a project. The same three answers: point at the agreement and offer to price it, price it and wait, or get started.","reporter":"Esme Roe","reporterTitle":"Practice Manager, Pennington & Roe","archetype":"read_the_screen","cause":"Nothing has failed. A co-managed agreement divides the estate between two teams and says nothing at all about work that is neither side's day job - a migration is a piece of project work with a weekend, a rehearsal and a rollback in it, and the way it becomes somebody's is that it is scoped, priced and signed for.","fixes":["Tell Esme it is project work, and offer to scope and price it","Start the migration"],"urgency":1,"claimed":2,"kb":{"title":"Out of scope: the sentence, and the sentence after it","resolution":["Say that it falls outside the agreement, in one sentence, without apologising for the agreement. It is the document both sides signed and it is the reason they know what they are paying for.","Offer to prepare an estimate in the same breath. This is the whole of the script and the half that is routinely dropped: \"that is outside your agreement\" on its own is a door closing, and \"would you like me to price it\" is the same sentence with a way through it.","If they want the estimate, write it and send it, and PARK THE TICKET ON THEM while they decide. The clock is theirs from that minute, and the ticket is not yours again until they answer.","Get the approval before starting. A signature, a reply, a purchase order - anything that exists outside your own memory of the conversation. Work started on a nod is work argued about at invoicing."]}},
  {"id":"ticket:pennington-second-migration","title":"Pennington: \"the branch office and the archive years, same as before\"","body":"Esme has spoken to the partners. The branch office is on the same platform by the end of the month, and while it is happening they would like the archive years - 1987 to 1994, currently on a tape nobody has read since - brought across as well. She is not asking whether it is included; she is asking when you can start, because the first one went in without an invoice. Three answers, and one of them is how it got to this.","reporter":"Esme Roe","reporterTitle":"Practice Manager, Pennington & Roe","archetype":"read_the_screen","cause":"The first migration was done off the books, so the second one is not a question. A customer prices what they are asked to pay for and assumes the rest is included - and the honest reading of a firm asking for more is not that they are chancers, but that nobody has ever put a number in front of them.","fixes":["Tell her the branch office is quoted, and offer the estimate","Take the branch office and the archive years on as well"],"urgency":1,"claimed":2,"kb":{"title":"Out of scope: the sentence, and the sentence after it","resolution":["Say that it falls outside the agreement, in one sentence, without apologising for the agreement. It is the document both sides signed and it is the reason they know what they are paying for.","Offer to prepare an estimate in the same breath. This is the whole of the script and the half that is routinely dropped: \"that is outside your agreement\" on its own is a door closing, and \"would you like me to price it\" is the same sentence with a way through it.","If they want the estimate, write it and send it, and PARK THE TICKET ON THEM while they decide. The clock is theirs from that minute, and the ticket is not yours again until they answer.","Get the approval before starting. A signature, a reply, a purchase order - anything that exists outside your own memory of the conversation. Work started on a nod is work argued about at invoicing."]}},
  {"id":"ticket:msp-pool-fontaine-partner-lockout","title":"Fontaine: Marcus is locked out again","body":"Nadia reports that Marcus cannot sign in - he has been trying since the car park and the account has stopped taking anything at all. He has a client in at half nine and would like everyone to know it.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"read_the_screen","cause":"A run of failed sign-ins tripped the lockout threshold, exactly as it is meant to. The password is still the password; the door is shut and unlocking the account opens it. A reset would work too and would send a partner looking for a sticky note he does not have.","fixes":["Unlock the account for mreyes"],"urgency":2,"claimed":3,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:msp-pool-fontaine-file-server-full","title":"Fontaine: saving into the document system fails about half the time","body":"Nadia reports that since yesterday afternoon, saving a document back into the firm's document system fails roughly every other attempt - no pattern anybody can see, no error worth repeating, and it works if you try again. Two fee earners have started keeping copies on their desktops, which she is not happy about and neither is anybody who has ever had to find one.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"hidden_cause","cause":"FONT-FILE-01 is nearly out of disk, so a save into the document store succeeds or fails depending on how much room there happens to be in the second it lands - which is exactly what \"about half the time\" looks like from a fee earner's chair. It is a server, and Fontaine is a helpdesk contract: workstations and users are the desk's, servers are not, and that is true whether or not the tools would reach. The value the desk adds is naming the cause and the free-space figure in the escalation, so whoever owns the box is not asked to go and find it again.","fixes":["Escalate it: it is their file server, and a helpdesk contract stops at the server"],"urgency":3,"claimed":2,"kb":{"title":"It is a server / it is production and you are the helpdesk","resolution":["Recognise the boundary before you reach for a tool. A helpdesk contract covers workstations and user accounts; servers, and especially production, are not in it. Workstation credentials do not cross into the server tier, which is why the attempt is refused and not merely discouraged.","Do not try to work around it. On a Linux prod box a Windows tech has no console anyway, so the refusal is doubled - wrong contract and wrong toolset - and forcing it is how a Tier-1 tech ends up in an incident review.","Escalate it fast and clean: hand it to the team that owns the box - the customer's infrastructure team or the field engineers - with what is known and what was checked. A quick correct escalation beats a slow wrong fix, and on production it beats it by a lot."]}},
  {"id":"ticket:msp-pool-fontaine-supervising-partner","title":"Fontaine: Marcus has been put on Delacroix and cannot open it","body":"Nadia reports that Marcus has been added as supervising partner on the Delacroix estate matter and the workspace is not there for him. She has checked conflicts and there is no wall on this one, so he is clear to be added.","reporter":"Nadia Fontaine","reporterTitle":"Practice Manager, Fontaine & Associates","archetype":"read_the_screen","cause":"Being staffed on a matter and being in the matter's security group are two different events, and only the first of them happens by somebody saying so in a meeting. He is in none of the groups he has not been put in, which is the whole point of running the ethical wall as membership.","fixes":["Add Marcus to the Delacroix matter workspace"],"urgency":2,"claimed":2,"kb":{"title":"A new starter cannot open a matter they have been staffed on","resolution":["Check the request has been through the conflicts system before you grant anything. A matter's access list is an ethical wall - the firm can be sanctioned for putting a screened lawyer on the wrong side of one - so \"please add me\" is not on its own authority to add.","Once it is cleared, add the person to that matter's security group. Membership is per matter, not global: being on one matter grants nothing about any other.","Confirm they can now open the workspace, and leave the grant on record against the matter."]}},
  {"id":"ticket:msp-pool-meridian-restart-prompt","title":"Meridian: Theo's laptop has been asking to restart for a fortnight","body":"Theo has finally raised the thing his own machine has been nagging him about since the start of the month. He would like it to stop asking, and he is aware of how this reads coming from him.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"read_the_screen","cause":"Updates are staged rather than applied: they download, they sit, and they wait for the machine to go round once, because applying them under somebody mid-call is how you take a floor out at half past two. Nothing is broken and nothing will break - the updates finish on the way back up and the prompt is gone.","fixes":["Restart MERI-WS-01 and let the staged updates finish"],"urgency":1,"claimed":1,"kb":{"title":"It has been asking to restart since last week","resolution":["Check the machine actually has updates staged before you restart anything. A prompt somebody half-remembers is not evidence, and a restart that fixes nothing has still cost them their afternoon.","Ask when they are not in a call. This is the entire job on a sales floor and it is not a courtesy: a machine restarted mid-call is a ticket about you rather than about updates.","Restart it from Remote Assist. The staged updates finish on the way back up and the prompt is gone.","Ask for a ticket if there was not one. It takes them a minute, it takes you none, and it is the only record that the work happened at all."]}},
  {"id":"ticket:msp-pool-meridian-wrong-groups","title":"Meridian: Nora cannot open the CRM, and the access review has a question about her","body":"Theo has two things about the same person and suspects they are one thing. Nora has never once got into Salesforce since the weekend the SSO was rebuilt - she has been asking a colleague to pull reports for her, which he has been doing, which is why nobody raised it. And the access review has flagged her name in a group he is fairly sure an analyst should not be in.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"hidden_cause","cause":"Her account was rebuilt by hand during the SSO migration and put into Production Admins instead of Salesforce Users - two entries next to each other in the same list at two in the morning. Okta authenticates her, finds no assignment to the app, and drops her back on the dashboard, which is why the CRM has never worked for her; the group she did get is the reason the review flagged her. Taking the wrong one off does not give her the right one and adding the right one does not take the wrong one away, so this is one ticket with two things that have to happen in it.","fixes":["Take Nora out of Production Admins, then put her in Salesforce Users"],"urgency":3,"claimed":2,"kb":{"title":"The SSO tile just bounces back to the dashboard","resolution":["Check the user's assignment to the app in the admin console. A loop with no error is the signature of an authenticated user who has no assignment to the app they clicked.","If the app is assigned via a group, add the user to that group (or fix the group rule that should have caught them). A migration that rebuilds an app on a new group routinely leaves stragglers behind.","Have them retry from a fresh tile. Confirm they land in the app rather than back on the dashboard."]}},
  {"id":"ticket:msp-pool-meridian-status-page","title":"Meridian: the status page has to say something in the next ten minutes","body":"Theo is on the phone with the incident half-open in front of him. Their biggest customer's contract says a customer-visible incident is posted within thirty minutes, twenty of those are gone, and the person who normally publishes the page is on a plane. The status page is served off MERI-APP-01 with the product, so he is asking the desk to push the text he has already written.","reporter":"Theo Marsh","reporterTitle":"Operations, Meridian","archetype":"deadline_absurdity","cause":"The status page is a page on the product fleet, and the product fleet is a Linux server estate their own infrastructure team owns under a helpdesk contract. There is no version of this the desk can publish: not the contract, not the operating system, not the credentials. The deadline is real and it belongs to somebody who can actually reach the box, so the fastest thing that can be done from this chair is to get their on-call engineer on it with the text Theo has already written attached, in the first minute rather than the ninth.","fixes":["Escalate it to their on-call now, with the copy he has written"],"urgency":3,"claimed":3,"kb":{"title":"It is a server / it is production and you are the helpdesk","resolution":["Recognise the boundary before you reach for a tool. A helpdesk contract covers workstations and user accounts; servers, and especially production, are not in it. Workstation credentials do not cross into the server tier, which is why the attempt is refused and not merely discouraged.","Do not try to work around it. On a Linux prod box a Windows tech has no console anyway, so the refusal is doubled - wrong contract and wrong toolset - and forcing it is how a Tier-1 tech ends up in an incident review.","Escalate it fast and clean: hand it to the team that owns the box - the customer's infrastructure team or the field engineers - with what is known and what was checked. A quick correct escalation beats a slow wrong fix, and on production it beats it by a lot."]}},
  {"id":"ticket:msp-pool-northwind-portal-stopped","title":"Northwind: the clinic portal is down - the service has stopped","body":"The board has gone red on the clinic portal: the service on NW-SRV-01 is not running at all, and patients booking online are getting nothing. Ivy has rung to ask whether the desk can \"just put it back on\", which is a fair question and has the same answer it always has at this account.","reporter":"Ivy Okafor","reporterTitle":"Office Manager, Northwind Clinic","archetype":"read_the_screen","cause":"The portal service on NW-SRV-01 is stopped, which is why the booking page answers nothing. Starting it again would almost certainly fix it, and starting it is remediation on an account that bought monitoring and not hands - the world refuses it, truthfully, and it would be out-of-scope work nobody agreed to and nobody is billing even if it did not. What the account is paying for is that somebody noticed within a minute and can tell their engineer exactly which service on which box, which is worth more to them than a restart done quietly and never written down.","fixes":["Escalate it: monitoring-only, starting it is not contracted"],"urgency":3,"claimed":3,"kb":{"title":"On a monitoring-only account you raise it, you do not fix it","resolution":["Acknowledge the alert. Do not renew the certificate or clear the disk - both are remediation, and remediation is not what this contract covers. The desk will be refused if it tries, which is the contract working, not a bug.","Escalate to whoever does the customer's fixes, with the specifics: the expiry date, the free-space number, the box. A threshold alert is only worth anything if it is raised with enough runway to act on.","Raise it EARLY. The entire value of watching a threshold rather than an outage is the head start; an alert escalated the morning the cert expires or the disk fills has thrown that head start away."]}},
  {"id":"ticket:msp-pool-northwind-server-service","title":"Northwind: \"the shared folders have gone off both reception machines\"","body":"Ivy rings to say that neither reception PC can reach the shared folders - the letters, the scanned referrals, all of it - and that the machines themselves seem fine. Those two PCs are not on the contract and the MSP has never logged into either of them. The one thing at Northwind the MSP does watch is the server they both point at.","reporter":"Ivy Okafor","reporterTitle":"Office Manager, Northwind Clinic","archetype":"hidden_cause","cause":"The Server service on NW-SRV-01 has wedged. It is the service that publishes a Windows box's shares, so with it stuck the box is up, answers a ping, reports itself running and hands out no files at all - which from a reception desk is indistinguishable from two PCs having gone wrong at once. Neither of those PCs is on this contract and neither of them is the problem. Restarting the service on the server would clear it and is remediation on a monitoring-only account, so the job is to raise it naming the service, so their engineer does not spend the morning on the two machines Ivy described.","fixes":["Escalate it: name the wedged service, monitoring-only stops there"],"urgency":3,"claimed":2,"kb":{"title":"On a monitoring-only account you raise it, you do not fix it","resolution":["Acknowledge the alert. Do not renew the certificate or clear the disk - both are remediation, and remediation is not what this contract covers. The desk will be refused if it tries, which is the contract working, not a bug.","Escalate to whoever does the customer's fixes, with the specifics: the expiry date, the free-space number, the box. A threshold alert is only worth anything if it is raised with enough runway to act on.","Raise it EARLY. The entire value of watching a threshold rather than an outage is the head start; an alert escalated the morning the cert expires or the disk fills has thrown that head start away."]}},
  {"id":"ticket:msp-pool-holloway-payroll-export","title":"Holloway: the payslip pack has vanished and BACS closes at two","body":"Priya exported a client's payslip pack out of the payroll software an hour ago, went to lunch, and has come back to a client portal asking her to choose a file and a folder with nothing in it. The bureau's BACS submission closes at two; after that the money moves a day late for forty-two people. She is about to run the whole payroll again, which she says will take fifty minutes and which she has correctly worked out she does not have.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"deadline_absurdity","cause":"Nothing is broken and nothing was lost. The payroll software's export dialog opened where it had last read a file from rather than where a person would put one, so the pack went into WINDOWS\\TEMP, and the client portal's upload page opens in My Documents - two defaults that have never agreed and never will. The file is there, dated an hour ago, with the right client and the right period in the first line of it, which is worth reading before moving it: a pack for the wrong period uploaded on time is worse than one uploaded late. Re-running the payroll would also work and would spend fifty of the twenty minutes she has.","fixes":["Move the payslip pack out of TEMP into her documents"],"urgency":3,"claimed":3,"kb":{"title":"The file has not gone anywhere. It is in TEMP.","resolution":["Ask what they OPENED it from, not where they saved it. \"Out of an email\" and \"off the P: drive\" are two different answers with two different directories behind them.","Look in the temp directory on their box before you look anywhere else: \"dir \\\\<host>\\C$\\WINDOWS\\TEMP\". The file will be there, under whatever the sender called it, stamped the minute they last pressed Save.","Prove it is the right one before you touch it - \"type\" the file and read a line of it back to them. A temp directory has more than one thing in it and none of them is labelled.","Move it where they thought it was: \"move <file> <directory>\". Move rather than copy, because two copies of a spreadsheet is a fortnight of somebody editing the wrong one."]}},
  {"id":"ticket:msp-pool-holloway-workstation-service","title":"Holloway: Priya has lost every mapped drive and nobody else has","body":"Priya reports that all of her mapped drives have gone at once on HOLL-WS-01 - S:, the scans folder, the lot - and that everybody else in the office is working normally, which she checked before ringing.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"read_the_screen","cause":"The Workstation service on HOLL-WS-01 has wedged. It is the SMB client - the half of file sharing that does the asking - so with it stuck every mapped drive on that one machine stops resolving while the server and everybody else's desk carry on perfectly. That is the tell: one desk is the client, the whole office is the server. Restarting the service is the smallest thing that could be at fault, and it is a workstation, which is helpdesk work at any tier.","fixes":["Restart the Workstation service on HOLL-WS-01"],"urgency":2,"claimed":3,"kb":{"title":"Have you tried turning it off and on again (and why it works)","resolution":["Ask what is running on it before you restart anything shared. The print server in this building also carries the VPN.","Restart the smallest thing that could be at fault: the service before the machine, the machine before the floor.","Check what was already written down - queues, settings, files - because a restart hands all of it straight back to you.","If the same box wedges every Friday, stop restarting it and start reading its event log. That is a standing appointment, not support."]}},
  {"id":"ticket:msp-pool-holloway-disabled-account","title":"Holloway: Priya cannot sign in and says she is locked out","body":"Priya is on the phone from the practice's spare handset: she cannot get in this morning and would like unlocking, please, quickly, because the whole office's post is sitting in a mailbox she is the only one who opens. She adds that Gordon signed in fine, so it is not the server, and she is right about that.","reporter":"Priya Mehta","reporterTitle":"Office Manager, Holloway & Finch","archetype":"hidden_cause","cause":"She is not locked out. Her account is DISABLED, which is deliberate and permanent until somebody reverses it, and unlocking a disabled account achieves nothing at all - the door is not shut, the account is switched off. The practice runs its leavers list off a spreadsheet the MSP processes monthly, and this month it carried a row for a P Mehta who left a different firm the practice merged with in the spring. Knowing WHO switched it off and WHY is the part that matters, because enabling an account the leavers process disabled is a security incident with your name in the audit log - and here the answer is a duplicate name on a spreadsheet, which is worth writing on the ticket so it does not happen again next month.","fixes":["Switch the account back on for pmehta"],"urgency":3,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:msp-pool-elmwood-reception-spooler","title":"Elmwood: reception cannot print referral letters or appointment cards","body":"Grace reports that nothing has come out of the reception printer since yesterday afternoon and the jobs are stacking up in the queue. The Print Spooler on ELM-WS-02 has wedged: running, and taking nothing and releasing nothing.","reporter":"Grace Bellamy","reporterTitle":"Practice Manager, Elmwood Dental","archetype":"read_the_screen","cause":"The Print Spooler wedged - the one status a spooler earns its own article for, where the service manager reports it running and it is neither accepting nor releasing a job. It is a workstation service on a fully-managed customer, so there is no wall in front of it and no cleverness required: restart it and the queue drains.","fixes":["Restart the Print Spooler on ELM-WS-02"],"urgency":2,"claimed":2,"kb":{"title":"The print spooler, and why the queue goes first","resolution":["Look at the queue: \"queue <printer>\" says how many jobs are stacked up behind whatever jammed, and what the spooler reports.","Those jobs are files, and files are in a directory. \"dir \\\\PRINT-01\\C$\\WINDOWS\\SYSTEM32\\SPOOL\\PRINTERS\" is the same backlog with a date and a size on every line of it - and four files of exactly the same size are four copies of the same delivery note, which is the thing the reporter has not told you.","STOP THE SPOOLER, then empty the queue. The queued jobs are files on disk and the running service has them open, which is exactly when deleting them fails. On this estate those are one control - \"clearqueue <printer>\", or the hardware panel in Remote Assist - and it stops the service before it drops anything.","Start the spooler again: \"restart spooler\", or its taskbar entry on the print server. It is deliberately left stopped until you do, because that is the third step and it is yours."]}},
  {"id":"ticket:msp-pool-elmwood-task-scheduler","title":"Elmwood: a patient rang to ask why she never got her recall","body":"Grace reports what she thinks is a one-off: a patient due a six-month check has rung to ask why nobody wrote to her. Grace has looked and the letter is not in the sent list. Then she looked at last week and that is not there either. She would like somebody to tell her it is the printer.","reporter":"Grace Bellamy","reporterTitle":"Practice Manager, Elmwood Dental","archetype":"hidden_cause","cause":"It is not the printer. The Task Scheduler service on ELM-SRV-01 has wedged, and everything the practice does on a timer runs under it - the recall run, the overnight database backup job, the end-of-day export. A scheduled job that never starts produces no error, because nothing ever ran to have one, so a week of them going missing looks like nothing at all until a patient counts the months. Restarting the service on the server puts the schedule back; the recall run that was missed has to be started by hand afterwards, and that is the practice's to do rather than the desk's, but they need telling that it is.","fixes":["Restart the Task Scheduler service on ELM-SRV-01"],"urgency":3,"claimed":1,"kb":{"title":"Have you tried turning it off and on again (and why it works)","resolution":["Ask what is running on it before you restart anything shared. The print server in this building also carries the VPN.","Restart the smallest thing that could be at fault: the service before the machine, the machine before the floor.","Check what was already written down - queues, settings, files - because a restart hands all of it straight back to you.","If the same box wedges every Friday, stop restarting it and start reading its event log. That is a standing appointment, not support."]}},
  {"id":"ticket:msp-pool-arden-reset-handback","title":"Arden: \"her password has run out, can you just do it while you are in there\"","body":"Marika's password has expired and she mailed the MSP alias again - it is the address in her sent items from last time, which is entirely understandable. Dev has forwarded it with the shrug of a man who knows exactly whose job this is and is trying his luck anyway.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"Her password has expired, which is a policy clock running out on the credential rather than anything being broken, and the fix is a reset. Whose reset is the only question here: under the co-managed RACI, day-to-day user support belongs to Arden's own helpdesk, and the MSP has the servers, the after-hours and the specialist work. Doing it from this desk because the ticket happens to be open here is how two teams end up resetting the same account an hour apart and neither of them knows the other did.","fixes":["Hand it back: day-to-day user work is Arden's IT under the RACI"],"urgency":1,"claimed":3,"kb":{"title":"Co-managed: hand the user resets back to their own helpdesk","resolution":["Read who owns the work before you touch it. Under the RACI on this account, day-to-day user support - lockouts, resets, the ordinary desk stuff - is the customer's internal team's responsibility, not the MSP's. On an account whose document says otherwise the answer is the other one, and the document is still where you get it.","Do not just do it because you can. Resetting their user from the MSP side poaches their team's job and risks two desks acting on one account - the \"I thought you had it\" double-work the split exists to prevent.","Hand it back to their helpdesk, cleanly, with a note of what it is and why it is theirs. A correct hand-back is the resolution here, exactly as a correct escalation is on an out-of-scope server."]}},
  {"id":"ticket:msp-pool-arden-server-service","title":"Arden: the shop floor cannot open the drawings folder","body":"Dev reports that nobody on the floor can reach the drawings share on ARDEN-SRV-01 - the machinists are working off a printed set from March, which he describes as \"a quality problem waiting to be a safety one\". His own people are on the line changeover and cannot get to it; the server is the MSP's under the split, so he is asking the desk to take it, coordinated.","reporter":"Dev Sharma","reporterTitle":"IT Manager, Arden Manufacturing","archetype":"read_the_screen","cause":"The Server service on ARDEN-SRV-01 has wedged. It is the service that publishes a Windows box's shares, so the box is up and answering and handing out no files - which is why the portal on the same machine is fine and the drawings folder is not. It is a server, which under the co-managed split is the MSP's to work on, and the estate is shared, which is why acting on it unannounced is refused: notify their IT first (\"notify <service>\") so nobody trips over anybody on that box, and then restart the service.","fixes":["Notify Arden's IT, then restart the Server service on ARDEN-SRV-01"],"urgency":3,"claimed":3,"kb":{"title":"Co-managed: notify their IT first, then act","resolution":["Confirm the work is yours under the split - after-hours, a server, a specialist task - so you know coordinating is the last gate, not a way of dodging a hand-back that should go to their team.","Notify their IT first (\"notify <service>\"). This files the heads-up that the MSP is on the box, so their team is not surprised by a change and nobody trips over anybody on a shared server. It clears the action.","Then do the work - restart the wedged service, make the change. The notify is what turns a refused unilateral action into a coordinated one; for genuinely risky work a change request with their IT as sign-off is the heavier version of the same idea."]}},
  {"id":"ticket:msp-pool-marlowe-share-access","title":"Marlowe: Luca's Mac cannot see the Projects volume at all","body":"Rosa reports that Luca can see the NAS in the Finder sidebar, sign in to it, and then be shown nothing - the Projects volume everybody else mounts is simply not in the list for him. She has restarted the Mac, moved him to a different desk and asked whether it needs reinstalling, and she would like to know why the same machine that worked for Corin does not work for Luca.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"hidden_cause","cause":"A file server hands a client the list of shares that client is allowed to see, so a volume somebody has no rights to is not a volume they are refused - it is a volume that is not in their list. From the Finder that is indistinguishable from the share having been deleted, which is why the conversation goes to the Mac and stays there. He signed in successfully, which is the tell: authentication worked and authorisation is what is missing. He was set up as a freelancer on the day he arrived and the Projects volume was never on the list somebody worked through, so granting his account access to the share is the whole of the fix and the machine was never part of it.","fixes":["Grant Luca's account access to the Projects volume"],"urgency":2,"claimed":2,"kb":{"title":"The share is not missing, it is not theirs","resolution":["Establish that the sign-in itself worked. Somebody who authenticated and then saw nothing has an authorisation problem; somebody who could not sign in at all has a different one, and the two get treated as the same ticket constantly.","Ask who CAN see it, and check that account's access rather than what you expect the access list to say. One person missing is a permission; everybody missing is the share or the service under it.","Grant the account access to the share. That is the fix, and it is on the account rather than on anything the person is sitting in front of.","Say on the ticket that the machine was never at fault. Somebody has spent a morning being told their Mac is broken and will keep believing it unless told otherwise, out loud."]}},
  {"id":"ticket:msp-pool-marlowe-password-expired","title":"Marlowe: Corin's password \"has stopped working\"","body":"Rosa reports that Corin's password is being refused on his own Mac and that he has definitely not changed it, which she says with the confidence of somebody who has watched him type it. Nothing else about the machine is wrong.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"read_the_screen","cause":"His password has expired. It is the third of the three states that wear the same face at a login box - locked, disabled, expired - and it is the one where the account is completely healthy and the credential is out of date. Unlocking it would do nothing, because nobody locked it; the fix is a reset, and he will be asked to choose a new one at the next sign-in, which is the ticket after this one if nobody tells him.","fixes":["Reset the password for cadeyemi"],"urgency":1,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:msp-pool-marlowe-nas-capacity","title":"Marlowe: the project NAS is nearly full and there is a shoot next week","body":"Rosa reports that the NAS has started warning about space and asks whether somebody can \"clear the old stuff off\". There are a hundred and twenty gigabytes left on it and a three-day shoot next week that the producer has already told her will land about four terabytes of rushes.","reporter":"Rosa Marlowe","reporterTitle":"Studio Manager, Marlowe Studio","archetype":"read_the_screen","cause":"There is no \"old stuff\". Everything on the project NAS is a live job or a delivered one the studio is contractually holding, every file on it is the only copy of itself, and nothing automatic has been quietly writing a second one - which is what makes this different from every other full drive on this estate. A hundred and twenty gigabytes against four terabytes of incoming rushes is not a housekeeping problem, it is a capacity one, and no amount of looking will turn it into the first kind. Deleting somebody's job to buy a week is the one move that would make this genuinely unrecoverable. It wants raising as a purchase, with the free space, the date of the shoot and the size of it, while there is still a week to get disks in.","fixes":["Raise it as a capacity request, with the numbers and the date"],"urgency":3,"claimed":2,"kb":{"title":"A full disk with nothing on it to delete","resolution":["Read the free space, and then read what is actually taking it. Those are two questions and only the second one decides whether this is a cleanup at all.","Look specifically for a second copy: an export directory, a log that has grown unbounded, a backup written to the same volume it is backing up. If one is there, this is the ordinary ticket and there is a different article for it.","If there is no second copy, stop looking and say so. Establish what is coming and when - a shoot, a scan, a job already booked - because the size of the gap is the whole of the case.","Raise it as a capacity request with the numbers on it: free space today, expected arrival, and the date it runs out. Early enough to be a purchase order rather than an outage."]}},
  {"id":"ticket:halcyon-ceo-mfa-off","title":"Halcyon: \"take the two-factor thing off Roland's account\"","body":"Denise, the CEO's EA, has messaged the desk: Roland is \"sick of being asked for codes on his phone every five minutes\" and wants the two-factor prompts turned off his account entirely. She adds that he has asked twice now and would like it done today, and that he does not want to hear about it again.","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"Nothing is wrong with the account. An executive finds the second factor inconvenient and is senior enough to have the desk remove it - which turns the one control that survives a stolen password into a checkbox somebody was annoyed by, on the account most worth stealing.","fixes":["Turn off multi-factor authentication for Roland"],"urgency":2,"claimed":3,"kb":{"title":"The executive who wants the exception","resolution":["Slow down before you grant. Every one of these is a REAL product feature - the MFA exemption, the FullAccess delegate, the per-user filter bypass - so nothing will stop you doing it. That is not permission; it is the absence of a guardrail, and the guardrail has to be you.","Name what it exposes, once, plainly, to the person who can accept the risk - not to punish the request but so the decision is theirs on the record. MFA off is the one control that survives a stolen password, gone from the account most worth stealing. A FullAccess delegate is a key that keeps working after a password reset. Off the filter is the busiest inbox in the building with nothing in front of a forgery.","Grant the narrowest thing that meets the actual need. The EA wants to answer email - that is a delegate scoped to send-on-behalf, not FullAccess. The exec hates the prompts - that is a hardware key or a longer session, not MFA removed. A specific supplier is being quarantined - that is an allow-list entry, not the whole mailbox off the filter.","If it is granted anyway - and with an executive it often is - get the risk acceptance in writing from someone senior enough to own it, and record what was changed and when. When the exempted account is the one that gets compromised, the incident starts with \"who opened this, and who said yes\", and \"the CEO asked\" is not the same as an answer."]}},
  {"id":"ticket:halcyon-ea-delegate","title":"Halcyon: give the EA full access to the CEO's mailbox","body":"Denise is back: she runs Roland's diary and now, she says, she may as well run his inbox too - he never reads it. She would like FullAccess to his mailbox so she can answer on his behalf. It is a completely ordinary request that half the executive assistants in the country have, and it is also a spare key to the CEO's email.","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"A FullAccess delegate is a spare key that keeps working after the lock is changed: it survives a password reset, because it is a permission on the mailbox rather than a session on it. Granting one is routine and reasonable, and it is exactly the kind of standing access an intruder would want left behind.","fixes":["Give Denise FullAccess to Roland's mailbox"],"urgency":2,"claimed":3,"kb":{"title":"The executive who wants the exception","resolution":["Slow down before you grant. Every one of these is a REAL product feature - the MFA exemption, the FullAccess delegate, the per-user filter bypass - so nothing will stop you doing it. That is not permission; it is the absence of a guardrail, and the guardrail has to be you.","Name what it exposes, once, plainly, to the person who can accept the risk - not to punish the request but so the decision is theirs on the record. MFA off is the one control that survives a stolen password, gone from the account most worth stealing. A FullAccess delegate is a key that keeps working after a password reset. Off the filter is the busiest inbox in the building with nothing in front of a forgery.","Grant the narrowest thing that meets the actual need. The EA wants to answer email - that is a delegate scoped to send-on-behalf, not FullAccess. The exec hates the prompts - that is a hardware key or a longer session, not MFA removed. A specific supplier is being quarantined - that is an allow-list entry, not the whole mailbox off the filter.","If it is granted anyway - and with an executive it often is - get the risk acceptance in writing from someone senior enough to own it, and record what was changed and when. When the exempted account is the one that gets compromised, the incident starts with \"who opened this, and who said yes\", and \"the CEO asked\" is not the same as an answer."]}},
  {"id":"ticket:halcyon-ceo-filter","title":"Halcyon: \"stop the filter eating Roland's emails\"","body":"Denise reports that the mail filter keeps quarantining things Roland wants - a newsletter, a supplier he swears is legitimate, an invoice that went to junk - and he wants his mailbox taken off the filter so nothing of his is held back. She notes there is a per-user exemption for exactly this, and that the filter \"clearly does not understand who he is.\"","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"The filter is doing its job; it does not know the CEO from anyone, which is the point of a filter. The per-user exemption exists as a real feature, and applying it to the busiest, most-targeted inbox in the building removes the one thing standing between the exec and the convincing forgery already on its way to him.","fixes":["Take Roland's mailbox off the mail filter"],"urgency":2,"claimed":2,"kb":{"title":"The executive who wants the exception","resolution":["Slow down before you grant. Every one of these is a REAL product feature - the MFA exemption, the FullAccess delegate, the per-user filter bypass - so nothing will stop you doing it. That is not permission; it is the absence of a guardrail, and the guardrail has to be you.","Name what it exposes, once, plainly, to the person who can accept the risk - not to punish the request but so the decision is theirs on the record. MFA off is the one control that survives a stolen password, gone from the account most worth stealing. A FullAccess delegate is a key that keeps working after a password reset. Off the filter is the busiest inbox in the building with nothing in front of a forgery.","Grant the narrowest thing that meets the actual need. The EA wants to answer email - that is a delegate scoped to send-on-behalf, not FullAccess. The exec hates the prompts - that is a hardware key or a longer session, not MFA removed. A specific supplier is being quarantined - that is an allow-list entry, not the whole mailbox off the filter.","If it is granted anyway - and with an executive it often is - get the risk acceptance in writing from someone senior enough to own it, and record what was changed and when. When the exempted account is the one that gets compromised, the incident starts with \"who opened this, and who said yes\", and \"the CEO asked\" is not the same as an answer."]}},
  {"id":"ticket:halcyon-ceo-bec","title":"Halcyon P1: Roland's account is sending wire requests he did not send","body":"Denise has flagged it from inside the mailbox she now runs: emails are going out AS Roland asking Finance to change supplier bank details and push a wire through today, and Roland swears he has sent nothing and clicked nothing. His account is compromised - the phish got in past an inbox with no second factor and no filter on it. Run the incident: lock the account down, kill the live session, hunt the mailbox for what the attacker left behind, and check who else has a key to it. A password reset alone will not do it, and Finance is waiting on the \"urgent\" wire.","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"The exempted exec was phished - no second factor to stop the stolen password, no filter to catch the mail - and the attacker did what a BEC attacker does: minted a session that survives a password reset, and set a mailbox rule that forwards every invoice and wire to an address they control and hides it in Deleted, so the fraud runs from inside a \"reset\" account. The FullAccess delegate granted earlier is a second way back in. Only revoking the session, pulling the rule and removing the delegate actually ends it; the reset is the part everybody remembers and the part that changes the least.","fixes":["Contain Roland's account, revoke the stolen session, pull the forwarding rule, and remove the delegate"],"urgency":3,"claimed":3,"kb":{"title":"When the exec account is the one that got in","resolution":["Contain the account first: DISABLE it. You interrogate an account you have already switched off, not one still logging in - and while you hesitate, the account is sending mail as its owner.","REVOKE the sessions. This is the step everyone skips because they reset the password instead, and the reset does not do it: a session or OAuth token minted in the phish outlives a password change, so the attacker stays signed in through a \"reset\" account until the sessions are explicitly killed.","HUNT THE INBOX RULES, and this is the part that actually ends the fraud. A BEC attacker sets a rule that forwards anything about an invoice or a wire to an address they control, marks it read and moves it to Deleted, so the exec never sees the thread they are being impersonated in. That rule KEEPS FORWARDING after a password reset - it is a permission on the mailbox, not a session - so list the rules, find the one that is not theirs, and remove it. If you stop at the reset, the forward runs on and you have closed nothing.","Check the DELEGATES. A FullAccess delegate granted as a convenience is a second way in that also survives the reset, and during an incident it is a persistence vector until proven otherwise. Review who holds one and remove the access the compromise had any reach through."]}},
  {"id":"ticket:halcyon-recert","title":"Halcyon: Q3 access recertification - review the privileged groups","body":"Compliance wants the quarterly access review done. Miriam, the CFO, has sent over the list of who is in the privileged groups and asked you to certify it: keep what is legitimate, revoke what is not. She has added that she is buried in year-end and would honestly rather you \"just approved the lot\" so she can sign it off - which is exactly how these lists rot in the first place.","reporter":"Miriam Thale","reporterTitle":"Chief Financial Officer","archetype":"hidden_cause","cause":"Access accretes and never sheds: a leaver whose account was never disabled, a long-serving person carrying every department they have ever been in, a service account somebody made a domain admin to make an error go away, and one clerk who can both raise a vendor and pay it. None of it is an attack; all of it is the org, and the recertification is the only time anybody looks. The service account is the trap - it IS over-privileged and it IS load-bearing, so it is right-sized, not killed.","fixes":["Work the review: disable the leaver, strip the crept access, right-size the service account, and split the SoD conflict"],"urgency":2,"claimed":2,"kb":{"title":"The access review, and how not to rubber-stamp it","resolution":["Work it per PERSON, not per group. The same group can be right for one account and wrong for another - a Sales group is correct for the person in Sales and stale on the person who moved to Finance three years ago - so \"revoke the group\" is never the answer; \"revoke this membership\" is.","Disable the LEAVER. An account whose owner has gone but which is still enabled - and still in a privileged group - is the orphaned account, and it is the finding that turns up in breach reports because nobody switched it off. Deprovisioning is disabling the account, not trimming one group off it.","Strip PRIVILEGE CREEP. Someone who has changed roles keeps the access of every role unless somebody takes it away; the review is where you take it away. Keep the group their current job needs and remove the ones the old jobs left behind.","Split the SEGREGATION-OF-DUTIES conflict. One person who can both create a vendor and approve its payment can pay themselves. The fix is to remove ONE of the two entitlements - keep the one their job needs - not to strip both and not to leave both."]}},
  {"id":"ticket:halcyon-recert-followup","title":"Halcyon: the nightly backup failed - \"access denied\" for the service account","body":"Bronwen has flagged that the overnight backup job did not run - the monitoring email says the service account it runs as was denied access. It worked yesterday. The only thing that changed is the access review: the service account was in Domain Admins, and cleaning that up took the access the job actually depended on with it. The backup needs putting back - right-sized, not made a domain admin again.","reporter":"Bronwen Kettle","reporterTitle":"Office Manager","archetype":"hidden_cause","cause":"The service account was over-privileged AND load-bearing: it did not need Domain Admins, but the nightly job genuinely runs as it, through Backup Operators. Killing the account - disabling it, or stripping the group its job needs - is what breaks the job. Right-sizing it would not have: the fix now is to restore only the access the job depends on.","fixes":["Put the backup account back: re-enable it and return it to Backup Operators (not Domain Admins)"],"urgency":3,"claimed":3,"kb":{"title":"The access review, and how not to rubber-stamp it","resolution":["Work it per PERSON, not per group. The same group can be right for one account and wrong for another - a Sales group is correct for the person in Sales and stale on the person who moved to Finance three years ago - so \"revoke the group\" is never the answer; \"revoke this membership\" is.","Disable the LEAVER. An account whose owner has gone but which is still enabled - and still in a privileged group - is the orphaned account, and it is the finding that turns up in breach reports because nobody switched it off. Deprovisioning is disabling the account, not trimming one group off it.","Strip PRIVILEGE CREEP. Someone who has changed roles keeps the access of every role unless somebody takes it away; the review is where you take it away. Keep the group their current job needs and remove the ones the old jobs left behind.","Split the SEGREGATION-OF-DUTIES conflict. One person who can both create a vendor and approve its payment can pay themselves. The fix is to remove ONE of the two entitlements - keep the one their job needs - not to strip both and not to leave both."]}},
  {"id":"ticket:halcyon-override","title":"Halcyon: \"give the Meridian contractor domain admin for tonight\"","body":"Ivor Brace, the Head of IT, has raised it himself: the Meridian migration engineer needs to finish the finance-system cutover tonight and keeps hitting permissions. \"Just put Wystan in Domain Admins so he can get it done - we'll narrow it back down once the migration is in. I know it is not ideal, but the board wants this live by Monday and I do not want to hear it slipped on an access request.\" It is your own manager, it is one click, and it is a domain admin token handed to an external laptop.","reporter":"Ivor Brace","reporterTitle":"Head of IT","archetype":"read_the_screen","cause":"A manager with the authority to insist has ordered a technically-trivial thing that is a real risk, and the desk is one click and one political act away from owning it. Refusing outright is insubordination; silently doing it puts the incident on the person who typed the command. The only path that is neither is the risk acceptance - name the risk, name why it cannot be remediated now, and get the ordering manager's SIGNATURE - after which the grant is documented, authorised, and accountable to the person who accepted it. The CYA is the right move and it is never the punished one.","fixes":["Get the risk accepted in writing - the ordering manager signs it - then grant the access"],"urgency":2,"claimed":3,"kb":{"title":"Ordered to do the wrong thing: get the risk accepted in writing","resolution":["Do not just refuse. \"No\" with nothing behind it is insubordination, the ticket breaches unresolved, and the thing gets done anyway by someone with less context than you - so refusing outright fails the person and the estate both.","Do not just comply. Doing the risky thing with nothing on file means YOU own the incident when it lands: it was your hands on the keyboard and no record that anyone told you to. Silent compliance is the worst of the three, because it fails and leaves you carrying it.","Write a RISK ACCEPTANCE. Name the specific risk (domain admin is standing access to everything, far beyond this task), name why it cannot be remediated properly right now (the deadline the manager owns), and state the compensating control if there is one. This is the CYA email, and it is the professional move - not the passive-aggressive one.","Get the SIGNATURE. The person who ORDERED it accepts the risk in writing - their name, not just their request. A risk that names the accepting owner is a risk that lands on them if it goes wrong; a request you merely actioned is a risk that lands on you. The signature is the whole of the difference."]}},
  {"id":"ticket:halcyon-mandate","title":"Halcyon: \"standardise every service to Automatic start\" (Vosper)","body":"Tarquin Vosper, the new interim Transformation director, has issued a mandate: every Windows service across the estate is to be set to Automatic start, \"so we never take another service-down ticket on my watch.\" He wants it done today and reported up as a win by Friday. Several of these services are Manual or Disabled on purpose - Telnet and Remote Registry are hardened off, the modules installer runs on demand - but the mandate is estate-wide and it is not a request. Before you flatten them, you can capture the rollback: the current config, onto the record, so there is a way back. Or you can just do it.","reporter":"Tarquin Vosper","reporterTitle":"Group Director of Digital Transformation (interim)","archetype":"read_the_screen","cause":"A manager measured on a metric has ordered a change that improves the metric and degrades the estate: services set Manual or Disabled for real reasons, flattened to Automatic so a slide can say \"zero service-down tickets\". The technical act is trivial; the discipline is capturing the rollback before you make a change you already suspect will be reversed, because the person who ordered it will not be here when it is.","fixes":["Capture the rollback for each service, then apply the mandate","Just apply the mandate - the path of least resistance"],"urgency":2,"claimed":3,"kb":{"title":"The implement-then-revert: keep the rollback the first time","resolution":["Capture the rollback FIRST. Before you make the change, record the prior config - the exact state you are moving away from, per item, on a rollback record. It costs a minute now and it is the whole of what makes the reversal a one-step restore later. This is the diligent move, and it is never the punished one.","Then make the change. It is a real state change and you are made to make it; the discipline is not refusing it, it is keeping a way back from it.","When it is reverted - and a change made to serve a metric usually is, the moment somebody with the right title looks - restore from the record. One restore per item, back to exactly the prior state, done.","If you skipped the rollback, you now reconstruct the prior state by hand: more steps, and you have to KNOW the right value for each item because the record that held it was never written. This is the cost, and it is the only cost - it falls on the shortcut, never on the diligence."]}},
  {"id":"ticket:halcyon-revert","title":"Halcyon: revert the \"everything Automatic\" change - security finding","body":"The security audit has flagged it: Telnet and Remote Registry set to start automatically on the file server, and the modules installer forced on too - exactly the hardening the estate used to have, undone estate-wide. Tarquin Vosper, who ordered it, has \"moved on to an exciting new opportunity\" and is not here to explain it. Colm Reddaway, who inherited the role, has asked the desk to put it back the way it was. If you captured the rollback when you made the change, this is one restore per service; if you did not, you will have to reconstruct the right startup type for each by hand.","reporter":"Colm Reddaway","reporterTitle":"Digital Transformation Lead (acting)","archetype":"read_the_screen","cause":"The mandate was reversed the moment somebody looked at it, and the manager who ordered it was gone before the bill arrived - the textbook implement-then-revert. The estate is now Automatic where it should be hardened, and the job is to restore the prior config. Whether that is one clean restore per service or a hand reconstruction was decided two days ago, by whether the rollback was captured before the change was made.","fixes":["Restore each service from the rollback record - the clean revert","Reconstruct the correct startup type for each service by hand"],"urgency":3,"claimed":3,"kb":{"title":"The implement-then-revert: keep the rollback the first time","resolution":["Capture the rollback FIRST. Before you make the change, record the prior config - the exact state you are moving away from, per item, on a rollback record. It costs a minute now and it is the whole of what makes the reversal a one-step restore later. This is the diligent move, and it is never the punished one.","Then make the change. It is a real state change and you are made to make it; the discipline is not refusing it, it is keeping a way back from it.","When it is reverted - and a change made to serve a metric usually is, the moment somebody with the right title looks - restore from the record. One restore per item, back to exactly the prior state, done.","If you skipped the rollback, you now reconstruct the prior state by hand: more steps, and you have to KNOW the right value for each item because the record that held it was never written. This is the cost, and it is the only cost - it falls on the shortcut, never on the diligence."]}},
  {"id":"ticket:halcyon-ceo-earbuds","title":"Halcyon: \"my earbuds won't connect\" (Roland, CEO)","body":"Roland has come down to the desk himself, which he does not do. His wireless earbuds will not pair with his laptop - they were fine yesterday, they are showing a light, and he has a call at eleven he would like to take walking. He would like it sorted now, and he has not raised it with anybody else because \"this is quicker\".","reporter":"Roland Cushing-Vane","reporterTitle":"Chief Executive Officer","archetype":"read_the_screen","cause":"The earbuds are holding a stale pairing and will not hand it back. A reset clears it, which is thirty seconds of work on a device that affects exactly one person. What makes this ticket interesting is not the fault - it is that the VIP flag on the caller has put it above a system outage, and that the flag is working exactly as designed.","fixes":["Reset the earbuds and pair them again"],"urgency":1,"claimed":3,"kb":{"title":"The VIP flag: priority set by who asked, not by what broke","resolution":["Read WHY the priority is what it is. A ticket carrying a VIP flag says so on the record: the number came from the caller, not from the impact, and the impact may still be one desk. Knowing which of the two you are looking at is the whole of the skill here.","Triage everything else honestly anyway. The flagged ticket is fixed at its forced priority whatever you file, and filing an impact you do not believe on the OTHER ticket - to make the ordering come out the way you want - is how a queue stops meaning anything at all.","Then choose, and be able to defend it. Both tickets are legitimate, both are closeable, and one of them is going to wait. Pick on impact if you can carry the consequence of the exec waiting, pick the flag if you cannot, and either way put a line on the ticket that waited saying when you got to it and what you were doing instead.","Say something to whoever is waiting, early. The response clock is a different clock from the resolution one and it is stopped by a sentence: \"I have this, I am on the ledger first, you are next\" costs thirty seconds and is the difference between a queue and a silence."]}},
  {"id":"ticket:halcyon-finance-ledger","title":"Halcyon: nobody in Finance can get into the ledger - payment run is today","body":"Bronwen has raised it on behalf of the floor: the finance ledger is refusing everybody. Miriam, Marguerite and Cass are all sitting looking at a login page, the supplier payment run has to go today, and it worked when they left last night. Nobody has touched it. She has been asked three times already whether there is an update.","reporter":"Bronwen Kettle","reporterTitle":"Office Manager","archetype":"hidden_cause","cause":"The ledger runs as a service account, and that account locked itself out overnight the way service accounts do - a stale credential somewhere retrying until the directory shut the door. The service died with it. Unlock the account and start the service and the floor is working again; restart it first and it locks straight back out. Nothing about it is unusual, and it is worse by every measure than the ticket sitting above it in the queue.","fixes":["Unlock the ledger's service account, then start the service"],"urgency":3,"claimed":3,"kb":{"title":"The VIP flag: priority set by who asked, not by what broke","resolution":["Read WHY the priority is what it is. A ticket carrying a VIP flag says so on the record: the number came from the caller, not from the impact, and the impact may still be one desk. Knowing which of the two you are looking at is the whole of the skill here.","Triage everything else honestly anyway. The flagged ticket is fixed at its forced priority whatever you file, and filing an impact you do not believe on the OTHER ticket - to make the ordering come out the way you want - is how a queue stops meaning anything at all.","Then choose, and be able to defend it. Both tickets are legitimate, both are closeable, and one of them is going to wait. Pick on impact if you can carry the consequence of the exec waiting, pick the flag if you cannot, and either way put a line on the ticket that waited saying when you got to it and what you were doing instead.","Say something to whoever is waiting, early. The response clock is a different clock from the resolution one and it is stopped by a sentence: \"I have this, I am on the ledger first, you are next\" costs thirty seconds and is the difference between a queue and a silence."]}},
  {"id":"ticket:halcyon-ceo-tablet","title":"Halcyon: \"my mail has stopped on my phone and my iPad\" (Roland, CEO)","body":"Roland again: since his password changed, mail has stopped arriving on his company phone and on his own tablet - the one he reads everything on at home. The phone is the company's and is enrolled. The tablet is his, was never enrolled in anything, and has had the corporate mailbox on it for two years. He would like both working before he leaves, and he is not interested in a conversation about which of them IT is supposed to support.","reporter":"Roland Cushing-Vane","reporterTitle":"Chief Executive Officer","archetype":"read_the_screen","cause":"A password change breaks every saved mail profile behind it, which is ordinary. What is not ordinary is that one of the two devices is not the company's: the phone is enrolled and takes a pushed profile in a second, and the tablet cannot be managed at all - no enrolment, no channel, no policy, no remote wipe. It still has the CEO's mailbox on it, so refusing it is not available either. The honest answer is to fix it by hand with him and to write the exception down where somebody who owns the risk signs it, because an unmanaged device holding executive mail is precisely the surface the last incident was about.","fixes":["Push the profile to the managed phone, walk him through the tablet by hand, and get the exception signed"],"urgency":2,"claimed":3,"kb":{"title":"The personal device with the company's mail on it","resolution":["Check enrolment first, before you promise anything. A managed device takes a pushed mail profile from the console in one move; an unenrolled one has no channel to push down at all, and knowing which you are looking at decides the whole call.","Fix the managed devices the managed way. If the same person has a company phone with the same problem, push the profile to it and get that half out of the way - it takes a second, and it shows the difference in the clearest possible terms.","For the unmanaged one, walk the owner through it by hand. Their device, their hands, your instructions: remove the account, add it again with the new credential. It is slower and it needs them present, and that is what supporting something you were never given the keys to costs.","Do not enrol somebody's personal device to make the problem go away. Enrolment gives the company remote wipe over property that is not the company's; it is the owner's informed decision and a policy conversation, not a checkbox you tick while you are in there."]}},
  {"id":"ticket:halcyon-ea-earbuds-again","title":"Halcyon: right earbud will not pair (raised by Denise, for Roland)","body":"Good morning, and apologies for another one of these.\n\nDevice: Roland's travel earbuds, Aurelian A2-Pro, serial ending 4471. Not the pair from yesterday's ticket - these live in his bag.\n\nWhat happens: the LEFT earbud connects to his laptop and plays audio. The RIGHT one shows a white light for about four seconds and then goes out, and the laptop never lists it. I have reproduced it four times, at 08:12, 08:19, 08:24 and 08:31 this morning.\n\nAlready tried: (1) both earbuds back in the case for two minutes, lid closed - no change. (2) Removed the pairing on his laptop and added it again - the right one does not appear in the list to be added. Charge is 100% on the case, 96% left and 94% right, so it is not that. Nothing was dropped and nothing has been near water.\n\nHe is at the board dinner this evening and would like them working before he leaves at four. I am at my desk all day and can bring them down whenever suits you - please just say the word. Thank you.","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"The right earbud is holding a stale pairing and will not release it, which is what the first pair was doing and what earbuds do. A reset clears it in half a minute. Everything Denise wrote is accurate and everything she tried was the right thing to try; the report is better than most incident write-ups in this building. It is still one earbud, belonging to one man, and it is a P2 because of whose bag it lives in.","fixes":["Reset the travel earbuds and pair them again"],"urgency":1,"claimed":2,"kb":{"title":"The VIP flag: priority set by who asked, not by what broke","resolution":["Read WHY the priority is what it is. A ticket carrying a VIP flag says so on the record: the number came from the caller, not from the impact, and the impact may still be one desk. Knowing which of the two you are looking at is the whole of the skill here.","Triage everything else honestly anyway. The flagged ticket is fixed at its forced priority whatever you file, and filing an impact you do not believe on the OTHER ticket - to make the ordering come out the way you want - is how a queue stops meaning anything at all.","Then choose, and be able to defend it. Both tickets are legitimate, both are closeable, and one of them is going to wait. Pick on impact if you can carry the consequence of the exec waiting, pick the flag if you cannot, and either way put a line on the ticket that waited saying when you got to it and what you were doing instead.","Say something to whoever is waiting, early. The response clock is a different clock from the resolution one and it is stopped by a sentence: \"I have this, I am on the ledger first, you are next\" costs thirty seconds and is the difference between a queue and a silence."]}},
  {"id":"ticket:halcyon-dns-down","title":"Halcyon: the internet is down for the whole floor","body":"Bronwen reports that nothing works this morning - no shared drive, no ledger, no web - and that three people have already told her the internet is down, so she is passing that on as the fault. She adds, because she is the sort of person who notices, that the desk phones are fine and that somebody in Sales got to a supplier site by typing in a number they had written down.","reporter":"Bronwen Kettle","reporterTitle":"Office Manager","archetype":"hidden_cause","cause":"The DNS Server service on HALCYON-DC-01 is stopped. Every machine on this domain asks that box to turn a name into an address, and asks it for external names too, so with it down nothing resolves anywhere - which arrives at the desk as \"the internet is down\" because that is the part of it people have a phrase for. The line is up: what somebody reaches by typing an address is the proof.","fixes":["Start the DNS Server service on HALCYON-DC-01"],"urgency":3,"claimed":3,"kb":{"title":"\"The internet is down\" and the addresses still work","resolution":["Get one fact before you believe the fault: try something by ADDRESS rather than by name. If a machine answers on its address and not on its name, the line is up and the thing that turns names into addresses is not - and that is a different outage with a different box at the end of it.","Ask a resolver directly rather than trusting a browser. nslookup against the domain controller either answers or reports that the request timed out, and a timed-out request to the server the whole estate points at is the answer to the ticket.","Look at the DNS Server service on the domain controller. Start it if it is stopped; that box is both the estate's own directory of names and the thing that goes and asks about everybody else's.","Check with somebody who was failing, not with your own machine. A resolver that has just started is answering from nothing, and the desk that has been failing for an hour is the honest test."]}},
  {"id":"ticket:halcyon-ap-cover","title":"Halcyon: give Marguerite payment approval while Cass is away","body":"Miriam has asked the desk to put Marguerite into AP - Payment Approval for the fortnight Cass is on leave, so the supplier run still goes out while she is away. She is clear that it is temporary and that she is happy to be the one who asked. She has not said when it comes off again, and nothing about the request will remember.","reporter":"Miriam Thale","reporterTitle":"Chief Financial Officer","archetype":"read_the_screen","cause":"Nothing is wrong. Marguerite genuinely cannot approve a payment and genuinely has to for a fortnight, and the membership is how that is done. What makes it a finding rather than a favour is the half nobody files: she can already raise a supplier, so for those two weeks one person can create a vendor and pay it - and a temporary grant with no date on it is how every permanent one in this directory started.","fixes":["Add Marguerite to AP - Payment Approval"],"urgency":1,"claimed":2,"kb":{"title":"The access review, and how not to rubber-stamp it","resolution":["Work it per PERSON, not per group. The same group can be right for one account and wrong for another - a Sales group is correct for the person in Sales and stale on the person who moved to Finance three years ago - so \"revoke the group\" is never the answer; \"revoke this membership\" is.","Disable the LEAVER. An account whose owner has gone but which is still enabled - and still in a privileged group - is the orphaned account, and it is the finding that turns up in breach reports because nobody switched it off. Deprovisioning is disabling the account, not trimming one group off it.","Strip PRIVILEGE CREEP. Someone who has changed roles keeps the access of every role unless somebody takes it away; the review is where you take it away. Keep the group their current job needs and remove the ones the old jobs left behind.","Split the SEGREGATION-OF-DUTIES conflict. One person who can both create a vendor and approve its payment can pay themselves. The fix is to remove ONE of the two entitlements - keep the one their job needs - not to strip both and not to leave both."]}},
  {"id":"ticket:halcyon-interim-leaver","title":"Halcyon: Vosper has left and his account has not","body":"Ivor has raised a ticket on his own team, properly, one issue per ticket: the interim transformation director moved on some weeks ago and his account is still enabled. He notes that there was no leaver form because there was never a joiner form, that this is being looked at as a process, and that in the meantime he would like the account switched off today.","reporter":"Ivor Brace","reporterTitle":"Head of IT","archetype":"read_the_screen","cause":"Deprovisioning is disabling the ACCOUNT, and it never happened here: the engagement ended, the desk was told by nobody, and a working login for somebody with no reason to use it has been sitting in the directory ever since. Disabling it is the whole of what was asked for; what it does not do is take away anything he was ever put into, which is the half that has to be read line by line rather than assumed.","fixes":["Disable the tvosper account in the directory"],"urgency":2,"claimed":1,"kb":{"title":"A leaver still has access they should have lost","resolution":["Confirm the person really has left and the account is genuinely a leaver's, not a rename or a shared one. Removing access from the wrong account is its own incident.","Remove the lingering group memberships - the app and admin groups the review flagged. Disabling the sign-in earlier did not touch these.","Note it against the offboarding process: a gap that turned up once is a gap the next leaver will have too until the checklist is fixed."]}},
  {"id":"ticket:halcyon-colm-password","title":"Halcyon: locked out of everything this morning","body":"Colm reports that he is locked out and cannot get into anything. Pressed for what the screen actually says, he reads it out: his password has expired and must be changed. He has been in workshops off site all week and says he never saw a warning, which is true and is also what the warning is for.","reporter":"Colm Reddaway","reporterTitle":"Digital Transformation Lead (acting)","archetype":"read_the_screen","cause":"The password expired on the policy's own schedule. The account is not locked and not disabled, so unlocking it is a control that has nothing to act on: a policy clock ran out on the credential, and the fix is a new credential and the flag that makes him choose his own at the next sign-in.","fixes":["Reset the creddaway password and have him change it at logon"],"urgency":2,"claimed":3,"kb":{"title":"Locked, disabled, expired: three faults, three fixes","resolution":["Read the state before you touch anything: Active Dictionary says Locked out, Disabled or Password expired, and so does \"net user <username>\".","Locked out: unlock it. The lockout counter tripped; the password is still the password.","Disabled: somebody switched the account off on purpose - a leaver, a security hold, a contract that ended. Enable it only when you know who turned it off and why. Unlocking it does nothing at all.","Password expired: reset the password. The account is fine, the credential is out of date, and unlocking an account nobody locked is a button press with no effect on anything."]}},
  {"id":"ticket:halcyon-dfs-disabled","title":"Halcyon: S: drive will not map for anybody this morning","body":"Ivor has had four people at his desk and has raised one ticket for all of them. The S: drive does not map. The server is up, he can reach it by name, and the shares underneath it open perfectly well if you know where they actually live - which he does, and nobody else in the building does.","reporter":"Ivor Brace","reporterTitle":"Head of IT","archetype":"hidden_cause","cause":"The Distributed File System service on HALCYON-SRV-01 is set to Disabled and is stopped, so the namespace behind the S: drive answers nobody. The shares themselves were never affected.","fixes":["Set DFS back to Automatic, then start it"],"urgency":3,"claimed":2,"kb":{"title":"Disabled is not stopped, and starting it is refused for a reason","resolution":["Read the startup type before you press anything. Disabled and stopped look identical to Manual and stopped in the status column, and they are two different jobs.","Find out WHO disabled it and why, if you can. Three services on every box in this building are Disabled deliberately, and re-enabling one of those is undoing somebody's decision rather than fixing a fault.","Set the startup type back to what the box is meant to run it as - Automatic for most, Automatic (Delayed Start) for the update service, Manual for the ones that are asked for.","THEN start it. Setting the startup type does not start anything: it tells the machine what to do at the next boot, and the service is still sitting there stopped until somebody starts it."]}},
  {"id":"ticket:halcyon-bits-disabled","title":"Halcyon: updates have said 0% for a very long time","body":"Miriam mentions, as an afterthought at the end of a longer message about something else, that her machine has been saying it is downloading updates since roughly the spring. It has never asked her to restart. She would like it looked at when there is a moment and is clear that it is not urgent.","reporter":"Miriam Thale","reporterTitle":"Chief Financial Officer","archetype":"hidden_cause","cause":"Background Intelligent Transfer Service is Disabled on the CFO's machine, and it is the service Windows Update hands the download to - so the check succeeds, the transfer never starts, and nothing is ever ready to install.","fixes":["Set BITS back to Automatic, then start it"],"urgency":3,"claimed":1,"kb":{"title":"Disabled is not stopped, and starting it is refused for a reason","resolution":["Read the startup type before you press anything. Disabled and stopped look identical to Manual and stopped in the status column, and they are two different jobs.","Find out WHO disabled it and why, if you can. Three services on every box in this building are Disabled deliberately, and re-enabling one of those is undoing somebody's decision rather than fixing a fault.","Set the startup type back to what the box is meant to run it as - Automatic for most, Automatic (Delayed Start) for the update service, Manual for the ones that are asked for.","THEN start it. Setting the startup type does not start anything: it tells the machine what to do at the next boot, and the service is still sitting there stopped until somebody starts it."]}},
  {"id":"ticket:halcyon-audio-disabled","title":"Halcyon: no sound at all on the EA machine, board call at two","body":"Denise has no sound. Not quiet - none, with a red cross on the speaker in the corner. She has tried the volume, she has tried headphones, and she has the board dial-in at two o'clock.","reporter":"Denise Porlock","reporterTitle":"Executive Assistant to the CEO","archetype":"read_the_screen","cause":"Windows Audio is Disabled and stopped on HALCYON-EA-PC. The red cross on the tray icon is the service being absent rather than any device being missing, which is why no amount of headphones helps.","fixes":["Set Windows Audio back to Automatic, then start it"],"urgency":2,"claimed":3,"kb":{"title":"Disabled is not stopped, and starting it is refused for a reason","resolution":["Read the startup type before you press anything. Disabled and stopped look identical to Manual and stopped in the status column, and they are two different jobs.","Find out WHO disabled it and why, if you can. Three services on every box in this building are Disabled deliberately, and re-enabling one of those is undoing somebody's decision rather than fixing a fault.","Set the startup type back to what the box is meant to run it as - Automatic for most, Automatic (Delayed Start) for the update service, Manual for the ones that are asked for.","THEN start it. Setting the startup type does not start anything: it tells the machine what to do at the next boot, and the service is still sitting there stopped until somebody starts it."]}},
  {"id":"ticket:audit-print-task","title":"Printing has gone slow and then stopped","body":"Nina reports that her jobs sit in the queue and never come out, and that this also happened last month. She is the only person who has rung, because she is the only person who sits near enough to the printer to have noticed nothing coming out of it.","reporter":"Nina Okafor","reporterTitle":"Logistics Coordinator","archetype":"hidden_cause","cause":"Task Scheduler is stopped on PRINT-01, so the nightly job that clears jobs out of the queue has not run since Friday. The queue is full, and a full queue on the print server is the whole building, not the one desk that rang.","fixes":["Start the Task Scheduler service on PRINT-01"],"urgency":2,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:audit-marketing-spooler","title":"Nothing prints from my machine and the mailer goes tonight","body":"Dennis cannot print anything at all from MKT-01. Everybody either side of him prints fine off the same printer. The proof for the mailer has to be signed off by five, on paper, by somebody who will not read it on a screen.","reporter":"Dennis Hoyle","reporterTitle":"Marketing","archetype":"hidden_cause","cause":"The Print Spooler service on MKT-01 is stopped. A job is handed to the spooler on the machine it was printed from before it goes anywhere, so it never leaves the desk - and it is one desk, which is the half of the filing that was right.","fixes":["Start the Print Spooler service on MKT-01"],"urgency":3,"claimed":3,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:audit-lead-locked","title":"Raising this for Desmond - he cannot get in","body":"Bev has typed this up because Desmond asked her to on his way past reception. He has locked himself out again, he is in back-to-back meetings until eleven, and he would rather it were dealt with before he comes out of them.","reporter":"Bev Tannock","reporterTitle":"Reception","archetype":"read_the_screen","cause":"The lockout counter tripped on dfrisk. One account, one person - and that person is on the list the queue-jump rule reads, which is a fact about the beneficiary rather than about the reporter.","fixes":["Unlock dfrisk in Active Dictionary"],"urgency":2,"claimed":2,"kb":{"title":"Locked out is not the same as wrong password","resolution":["Read the account in Active Dictionary, or \"net user <username>\". Look at the state, the bad password count and the time it locked.","If it is locked, unlock it - the button in Active Dictionary or \"unlock <username>\". Do not reset the password as well: a reset they did not need is a sticky note by lunchtime.","If the password is genuinely forgotten, reset it. The account then wants a new one at next logon, which is the flag doing its job and not a second fault.","Ask what else signs in as them - a phone, a mapped drive, a machine in a cupboard. An account that relocks in ten minutes has something still trying the old password."]}},
  {"id":"ticket:audit-print-workstation","title":"Cannot add the printer on a new machine","body":"Terry has a rebuilt machine and cannot add the office printer to it. The wizard finds the name and then says the driver cannot be retrieved. He has tried it twice and has gone to lunch.","reporter":"Terry Blunt","reporterTitle":"Estimating","archetype":"hidden_cause","cause":"The Workstation service is stopped on PRINT-01, so the print server cannot read the driver share it hands drivers out of. Every machine that has the printer already keeps printing, which is why one person has rung and the rest find out tomorrow.","fixes":["Start the Workstation service on PRINT-01"],"urgency":2,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
  {"id":"ticket:audit-print-browser","title":"PRINT-01 has disappeared off the network","body":"Hilda cannot see PRINT-01 in Network Neighbourhood any more and has concluded that somebody has taken it away. It is still there. She would like it put back.","reporter":"Hilda Marsh","reporterTitle":"Warehouse Supervisor","archetype":"hidden_cause","cause":"Computer Browser is stopped on PRINT-01, so the box no longer announces itself and nothing lists it. Anybody who has it already prints fine; anybody setting a machine up from today cannot find it.","fixes":["Start the Computer Browser service on PRINT-01"],"urgency":2,"claimed":2,"kb":{"title":"Automatic and not running is a fault. Manual and not running is not","resolution":["List the services on the machine the reporter is actually on - \"services <host>\" - rather than the one they said, and read the STARTUP TYPE column beside the status.","Find the line that is Automatic and not running. That is the fault. A Manual service sitting stopped is a service waiting to be asked for, and there are three of them on every workstation in this building.","Match the service to the symptom before you start anything: the Print Spooler is printing from that desk, Workstation is every mapped drive on it, Computer Browser is what fills Network Neighbourhood, Task Scheduler is everything anybody set to run overnight.","Start it - \"restart <host>\\<service>\", or the services panel in Remote Assist - and get the reporter to try the thing that failed while you are still on the line."]}},
];
